"use client";

import {
  createContext,
  useContext,
  useMemo,
  type CSSProperties,
  type ReactNode,
} from "react";
import type { FillStyle } from "../types";

export type DoodleUITheme = "light" | "dark" | "system";

/**
 * Values exposed by {@link DoodleUIProvider} to hooks and descendant components.
 */
export interface DoodleUIContextValue {
  /**
   * Default for components that do not set their own `animate` prop.
   * @default true
   */
  animate: boolean;
  /**
   * When true, skip the prefers-reduced-motion disable.
   * @default false
   */
  forceAnimate: boolean;
  /**
   * Theme mode for {@link useSketchTheme} palette resolution.
   * @default "system"
   */
  theme?: DoodleUITheme;
  /**
   * Global default roughness for sketch chrome when a component omits `roughness`.
   * @default undefined (use CSS var or {@link DEFAULT_ROUGHNESS})
   */
  roughness?: number;
  /**
   * Global default stroke width when a component omits `strokeWidth`.
   * @default undefined (use CSS var or {@link DEFAULT_STROKE_WIDTH})
   */
  strokeWidth?: number;
  /**
   * Global default stroke color when a component omits `sketchColor`.
   * @default undefined (theme ink)
   */
  sketchColor?: string;
  /**
   * Global default fill pattern when a component has a fill but omits `fillStyle`.
   * @default undefined
   */
  fillStyle?: FillStyle;
  /**
   * Global default bowing when a component omits `bowing`.
   * @default undefined (use CSS var or {@link DEFAULT_BOWING})
   */
  bowing?: number;
}

const DoodleUIContext = createContext<DoodleUIContextValue | null>(null);

/**
 * Root provider for doodle-ui animation defaults, light/dark sketch palette, and
 * optional global sketch parameters (roughness, stroke, fill style, bowing).
 *
 * @example
 * <DoodleUIProvider roughness={2} strokeWidth={2} theme="light">
 *   <Button>Sketchy</Button>
 * </DoodleUIProvider>
 *
 * @see SketchSeedProvider
 */
export interface DoodleUIProviderProps {
  children: ReactNode;
  /**
   * Default animation setting for descendant doodle-ui components.
   * Per-component `animate` still wins when it is set.
   * @default true
   */
  animate?: boolean;
  /**
   * Play animations even when the user prefers reduced motion.
   * @default false
   */
  forceAnimate?: boolean;
  /**
   * Theme mode: `"light"`, `"dark"`, or `"system"` (follows document / OS).
   * @default "system"
   */
  theme?: DoodleUITheme;
  /**
   * Default sketch roughness for descendants. Also sets `--doodle-ui-roughness` on the provider scope.
   * @default undefined
   * @example
   * <DoodleUIProvider roughness={2.4} />
   */
  roughness?: number;
  /**
   * Default stroke width for descendants. Also sets `--doodle-ui-stroke-width`.
   * @default undefined
   */
  strokeWidth?: number;
  /**
   * Default stroke color for descendants. Also sets `--doodle-ui-stroke-color`.
   * @default undefined
   */
  sketchColor?: string;
  /**
   * Default fill style when shapes have a fill. Also sets `--doodle-ui-fill-style`.
   * @default undefined
   */
  fillStyle?: FillStyle;
  /**
   * Default line bowing for descendants. Also sets `--doodle-ui-bowing`.
   * @default undefined
   */
  bowing?: number;
}

export function DoodleUIProvider({
  children,
  animate = true,
  forceAnimate = false,
  theme = "system",
  roughness,
  strokeWidth,
  sketchColor,
  fillStyle,
  bowing,
}: DoodleUIProviderProps) {
  const value = useMemo(
    () => ({
      animate,
      forceAnimate,
      theme,
      roughness,
      strokeWidth,
      sketchColor,
      fillStyle,
      bowing,
    }),
    [
      animate,
      forceAnimate,
      theme,
      roughness,
      strokeWidth,
      sketchColor,
      fillStyle,
      bowing,
    ],
  );

  const scopeStyle = useMemo((): CSSProperties => {
    const vars: Record<string, string | number> = {};
    if (roughness !== undefined) vars["--doodle-ui-roughness"] = roughness;
    if (strokeWidth !== undefined) vars["--doodle-ui-stroke-width"] = strokeWidth;
    if (sketchColor !== undefined) vars["--doodle-ui-stroke-color"] = sketchColor;
    if (fillStyle !== undefined) vars["--doodle-ui-fill-style"] = fillStyle;
    if (bowing !== undefined) vars["--doodle-ui-bowing"] = bowing;
    if (Object.keys(vars).length === 0) return {};
    return vars as CSSProperties;
  }, [roughness, strokeWidth, sketchColor, fillStyle, bowing]);

  const hasScopeVars = Object.keys(scopeStyle).length > 0;

  return (
    <DoodleUIContext.Provider value={value}>
      {hasScopeVars ? (
        <div style={{ display: "contents", ...scopeStyle }}>{children}</div>
      ) : (
        children
      )}
    </DoodleUIContext.Provider>
  );
}

/**
 * Reads animation and sketch defaults from the nearest {@link DoodleUIProvider}.
 * Returns built-in defaults when no provider is mounted.
 *
 * @returns Provider context or `{ animate: true, forceAnimate: false, theme: "system" }`.
 *
 * @example
 * const { animate, roughness } = useDoodleUI();
 */
export function useDoodleUI(): DoodleUIContextValue {
  return (
    useContext(DoodleUIContext) ?? { animate: true, forceAnimate: false, theme: "system" }
  );
}

export { DoodleUIContext };

export {
  DoodleUIProvider,
  useDoodleUI,
  DoodleUIContext,
  type DoodleUIProviderProps,
  type DoodleUIContextValue,
  type DoodleUITheme,
} from "./DoodleUIProvider";
export { resolveAnimate, type ResolveAnimateInput } from "./resolveAnimate";
export { useAnimate } from "./useAnimate";
export { useTweenNumber } from "./useTweenNumber";
export { usePrefersReducedMotion } from "./usePrefersReducedMotion";
export {
  useDrawIn,
  drawIn,
  cancelDrawIn,
  getStrokePaths,
  DRAW_IN_DURATION_MS,
  DRAW_IN_ALERT_MS,
  DRAW_IN_TOOLTIP_MS,
  DRAW_IN_MARK_MS,
  TABLE_STAGGER_MS,
} from "./useDrawIn";

export interface ResolveAnimateInput {
  /** Per-component override. When set, wins over the provider default. */
  animate?: boolean;
  /** Provider default. Defaults to true. */
  providerAnimate?: boolean;
  /** Ignore prefers-reduced-motion when true. */
  forceAnimate?: boolean;
  prefersReducedMotion?: boolean;
}

/**
 * Resolve whether sketch animations should run.
 * `prefers-reduced-motion: reduce` wins unless `forceAnimate` is set.
 * An explicit per-component `animate` prop then wins over the provider.
 */
export function resolveAnimate({
  animate,
  providerAnimate = true,
  forceAnimate = false,
  prefersReducedMotion = false,
}: ResolveAnimateInput): boolean {
  if (prefersReducedMotion && !forceAnimate) return false;
  if (animate !== undefined) return animate;
  return providerAnimate;
}

"use client";

import { useDoodleUI } from "./DoodleUIProvider";
import { resolveAnimate } from "./resolveAnimate";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Whether the calling component should play sketch animations.
 *
 * @param animate - Per-component override; when set, wins over the provider
 * @returns `true` when draw-in / morph animations should run
 *
 * @example
 * const shouldAnimate = useAnimate(props.animate);
 */
export function useAnimate(animate?: boolean): boolean {
  const { animate: providerAnimate, forceAnimate } = useDoodleUI();
  const prefersReducedMotion = usePrefersReducedMotion();
  return resolveAnimate({
    animate,
    providerAnimate,
    forceAnimate,
    prefersReducedMotion,
  });
}

"use client";

import { useLayoutEffect, type RefObject } from "react";

/** Default sketch-in duration. Ease-out over ~400ms. */
export const DRAW_IN_DURATION_MS = 400;
/** Alerts often appear dynamically — keep the sketch-in snappy. */
export const DRAW_IN_ALERT_MS = 200;
/** Tooltips are transient — draw in quickly. */
export const DRAW_IN_TOOLTIP_MS = 180;
/** Checkmarks, radio dots, and tab underlines. */
export const DRAW_IN_MARK_MS = 240;
/** Delay between table row rules. */
export const TABLE_STAGGER_MS = 40;

const DRAW_IN_EASING = "ease-out";

const running = new WeakMap<Element, Animation[]>();

/**
 * Rough.js puts fill (hachure) first and the outline last inside each `<g>`.
 * Animate the outline path so the border sketches in, not the wash.
 */
function collectStrokePaths(root: Element): SVGPathElement[] {
  const groups = root.querySelectorAll("g");
  if (groups.length > 0) {
    const paths: SVGPathElement[] = [];
    groups.forEach((group) => {
      const children = group.querySelectorAll(":scope > path");
      if (children.length === 0) return;
      paths.push(children[children.length - 1] as SVGPathElement);
    });
    return paths;
  }
  return Array.from(root.querySelectorAll("path"));
}

export function getStrokePaths(target: Element): SVGPathElement[] {
  if (target instanceof SVGPathElement) return [target];
  if (target instanceof SVGSVGElement) return collectStrokePaths(target);

  const svgs = target.querySelectorAll("svg");
  if (svgs.length > 0) {
    return Array.from(svgs).flatMap((svg) => collectStrokePaths(svg));
  }
  return collectStrokePaths(target);
}

function clearDash(path: SVGPathElement) {
  path.style.strokeDasharray = "";
  path.style.strokeDashoffset = "";
}

export function cancelDrawIn(target: Element | null): void {
  if (!target) return;
  const animations = running.get(target);
  animations?.forEach((animation) => animation.cancel());
  running.delete(target);
  getStrokePaths(target).forEach(clearDash);
}

export function drawIn(
  target: Element,
  duration: number = DRAW_IN_DURATION_MS,
  delay: number = 0,
): void {
  cancelDrawIn(target);
  const paths = getStrokePaths(target);
  const animations: Animation[] = [];

  for (const path of paths) {
    let length = 0;
    try {
      length = path.getTotalLength();
    } catch {
      continue;
    }
    if (length <= 0) continue;

    path.style.strokeDasharray = `${length}`;
    path.style.strokeDashoffset = `${length}`;

    const animation = path.animate(
      [{ strokeDashoffset: String(length) }, { strokeDashoffset: "0" }],
      { duration, delay, easing: DRAW_IN_EASING, fill: "forwards" },
    );
    animation.finished
      .then(() => {
        clearDash(path);
      })
      .catch(() => {
        /* cancelled */
      });
    animations.push(animation);
  }

  running.set(target, animations);
}

/**
 * Sketch-in the rough.js stroke path on the first paint, and again when
 * `replayKey` changes (e.g. a hover seed swap).
 *
 * @param pathRef - Ref to an SVG path, `<svg>`, or container with sketch paths
 * @param duration - Animation duration in ms
 * @default 400 ({@link DRAW_IN_DURATION_MS})
 * @param enabled - When false, cancels any in-flight draw-in
 * @default true
 * @param replayKey - When this value changes, the stroke redraws
 * @param delay - Delay before the animation starts (ms)
 * @default 0
 *
 * @example
 * const ref = useRef<HTMLDivElement>(null);
 * useDrawIn(ref, DRAW_IN_DURATION_MS, shouldAnimate, seed);
 */
export function useDrawIn(
  pathRef: RefObject<Element | null>,
  duration: number = DRAW_IN_DURATION_MS,
  enabled: boolean = true,
  replayKey?: unknown,
  delay: number = 0,
): void {
  useLayoutEffect(() => {
    const target = pathRef.current;
    if (!target) return;

    if (!enabled) {
      cancelDrawIn(target);
      return;
    }

    const apply = () => drawIn(target, duration, delay);

    if (getStrokePaths(target).length > 0) {
      apply();
      return () => cancelDrawIn(target);
    }

    const observer = new MutationObserver(() => {
      if (getStrokePaths(target).length === 0) return;
      observer.disconnect();
      apply();
    });
    observer.observe(target, { childList: true, subtree: true });

    return () => {
      observer.disconnect();
      cancelDrawIn(target);
    };
  }, [pathRef, duration, enabled, replayKey, delay]);
}

"use client";

import { useSyncExternalStore } from "react";

function subscribe(onStoreChange: () => void) {
  const media = window.matchMedia("(prefers-reduced-motion: reduce)");
  media.addEventListener("change", onStoreChange);
  return () => media.removeEventListener("change", onStoreChange);
}

function getSnapshot() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function getServerSnapshot() {
  return false;
}

export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Ease a number toward `target`. When `enabled` is false, snap immediately.
 */
export function useTweenNumber(
  target: number,
  enabled: boolean,
  duration: number = 400,
): number {
  const [value, setValue] = useState(target);
  const valueRef = useRef(target);
  valueRef.current = value;

  useEffect(() => {
    if (!enabled) {
      valueRef.current = target;
      setValue(target);
      return;
    }

    const from = valueRef.current;
    if (from === target) return;

    const start = performance.now();
    let frame = 0;
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - (1 - t) ** 3;
      const next = from + (target - from) * eased;
      valueRef.current = next;
      setValue(next);
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [target, enabled, duration]);

  return enabled ? value : target;
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useLayoutEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { nextFontIndex, randomSeed } from "../utils";

/**
 * Seed and font shuffle state from {@link SketchSeedProvider}.
 */
export interface SketchSeedContextValue {
  /**
   * Current sketch seed shared by components without an explicit `seed` prop.
   * Changes when {@link SketchSeedContextValue.shuffle} runs.
   */
  seed: number;
  /**
   * Index into the provider `fonts` array. `0` means page default font.
   */
  fontIndex: number;
  /**
   * Picks a new random seed and advances the font palette index.
   */
  shuffle: () => void;
  /**
   * Sets the shared seed explicitly (e.g. for reproducible layouts).
   * @param seed - Integer seed for rough.js
   */
  setSeed: (seed: number) => void;
}

const SketchSeedContext = createContext<SketchSeedContextValue | null>(null);

/**
 * Props for {@link SketchSeedProvider}.
 */
export interface SketchSeedProviderProps {
  children: ReactNode;
  /**
   * Initial shared sketch seed. Random when omitted.
   * @default undefined (random on mount)
   */
  initialSeed?: number;
  /**
   * CSS `font-family` values cycled by Shuffle. Index `0` is the page default
   * (`--doodle-ui-font` left unset).
   * @default undefined
   * @example
   * <SketchSeedProvider fonts={['"Patrick Hand"', '"Kalam"']} />
   */
  fonts?: readonly string[];
  /**
   * Starting index into `fonts`.
   * @default 0
   */
  initialFontIndex?: number;
}

/**
 * Supplies a shared sketch seed and optional hand-font cycling for Shuffle.
 * Wrap your app next to {@link DoodleUIProvider}.
 *
 * @example
 * <SketchSeedProvider>
 *   <Button onClick={() => shuffle()}>Redraw</Button>
 * </SketchSeedProvider>
 *
 * @see useSketchSeed
 */
export function SketchSeedProvider({
  children,
  initialSeed,
  fonts,
  initialFontIndex = 0,
}: SketchSeedProviderProps) {
  const [seed, setSeed] = useState(() => initialSeed ?? randomSeed());
  const [fontIndex, setFontIndex] = useState(initialFontIndex);
  const fontCount = fonts?.length ?? 0;

  const shuffle = useCallback(() => {
    setSeed(randomSeed());
    setFontIndex((current) => nextFontIndex(current, fontCount));
  }, [fontCount]);

  const activeFamily = fontIndex > 0 ? fonts?.[fontIndex] : undefined;

  useLayoutEffect(() => {
    const root = document.documentElement;
    if (activeFamily) {
      root.style.setProperty("--doodle-ui-font", activeFamily);
      root.style.setProperty("--doodle-ui-font-weight", "400");
    } else {
      root.style.setProperty("--doodle-ui-font", "initial");
      root.style.setProperty("--doodle-ui-font-weight", "initial");
    }
    return () => {
      root.style.removeProperty("--doodle-ui-font");
      root.style.removeProperty("--doodle-ui-font-weight");
    };
  }, [activeFamily]);

  const value = useMemo(
    () => ({ seed, fontIndex, shuffle, setSeed }),
    [seed, fontIndex, shuffle],
  );

  return (
    <SketchSeedContext.Provider value={value}>
      {children}
    </SketchSeedContext.Provider>
  );
}

/**
 * Returns shared seed and shuffle helpers from {@link SketchSeedProvider}.
 *
 * @throws When used outside `<SketchSeedProvider>`.
 *
 * @example
 * const { seed, shuffle } = useSketchSeed();
 */
export function useSketchSeed(): SketchSeedContextValue {
  const ctx = useContext(SketchSeedContext);
  if (!ctx) {
    throw new Error(
      "useSketchSeed() must be used inside <SketchSeedProvider>. Wrap your tree so Shuffle can redraw every sketch.",
    );
  }
  return ctx;
}

export function useOptionalSketchSeed(): SketchSeedContextValue | null {
  return useContext(SketchSeedContext);
}

export { SketchSeedContext };

"use client";

import { useLayoutEffect, useState, type RefObject } from "react";

export function useElementSize(
  ref: RefObject<HTMLElement | null>,
): { width: number; height: number } {
  const [size, setSize] = useState({ width: 0, height: 0 });

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;

    const update = () => {
      setSize({ width: el.offsetWidth, height: el.offsetHeight });
    };

    update();
    const observer = new ResizeObserver(update);
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  return size;
}

"use client";

import { useState } from "react";
import { useOptionalSketchSeed } from "../context/SketchSeedContext";
import { randomSeed } from "../utils";

/**
 * Resolves the seed used to draw a sketch.
 *
 * Priority: explicit `seed` prop → {@link SketchSeedProvider} → stable mount random.
 *
 * @param seed - Optional locked seed from a component prop
 * @returns Integer seed for rough.js
 *
 * @example
 * const resolved = useResolvedSeed(props.seed);
 */
export function useResolvedSeed(seed?: number): number {
  const ctx = useOptionalSketchSeed();
  const [fallback] = useState(randomSeed);
  if (seed != null) return seed;
  if (ctx) return ctx.seed;
  return fallback;
}

"use client";

export {
  SketchSeedProvider,
  useSketchSeed,
  useOptionalSketchSeed,
  type SketchSeedContextValue,
  type SketchSeedProviderProps,
} from "../context/SketchSeedContext";

"use client";

import { useEffect, useState } from "react";
import { useDoodleUI } from "../animations/DoodleUIProvider";
import {
  DARK_SKETCH_COLORS,
  DEFAULT_DARK_CARD_BG,
  DEFAULT_DARK_INK,
  DEFAULT_DARK_PAPER,
  DEFAULT_INK,
  DEFAULT_PAPER,
  SKETCH_COLORS,
} from "../types";

export interface ResolvedSketchTheme {
  isDark: boolean;
  ink: string;
  paper: string;
  cardBg: string;
  shadow: string;
  accent: string;
  accentFill: string;
  secondaryFill: string;
  info: string;
  warning: string;
  error: string;
  success: string;
}

export type SketchTheme = ResolvedSketchTheme;

function checkIsDark(): boolean {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return false;
  }
  const root = document.documentElement;
  if (root.classList.contains("dark")) return true;
  const dataTheme = root.getAttribute("data-theme");
  if (dataTheme === "dark") return true;
  if (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches) {
    return true;
  }
  return false;
}

/**
 * Resolves ink, paper, accent, and status colors from {@link DoodleUIProvider}
 * theme mode and optional stroke override.
 *
 * @param sketchColorOverride - Same as component `sketchColor` prop
 * @returns Palette tokens for the current light/dark mode
 *
 * @example
 * const { ink, paper, accent } = useSketchTheme(sketchColor);
 */
export function useSketchTheme(sketchColorOverride?: string): ResolvedSketchTheme {
  const doodleContext = useDoodleUI();
  const contextTheme = doodleContext?.theme;

  const [isClientDark, setIsClientDark] = useState<boolean>(() => {
    if (contextTheme === "dark") return true;
    if (contextTheme === "light") return false;
    return checkIsDark();
  });

  useEffect(() => {
    if (contextTheme === "dark") {
      setIsClientDark(true);
      return;
    }
    if (contextTheme === "light") {
      setIsClientDark(false);
      return;
    }

    // "system" / "auto" mode: detect from DOM and media query
    const update = () => {
      setIsClientDark(checkIsDark());
    };
    update();

    const mediaQuery = window.matchMedia?.("(prefers-color-scheme: dark)");
    mediaQuery?.addEventListener?.("change", update);

    const observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        if (m.attributeName === "class" || m.attributeName === "data-theme") {
          update();
          break;
        }
      }
    });

    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme"],
    });

    return () => {
      mediaQuery?.removeEventListener?.("change", update);
      observer.disconnect();
    };
  }, [contextTheme]);

  const isDark = contextTheme === "dark" ? true : contextTheme === "light" ? false : isClientDark;

  const baseInk = isDark ? DEFAULT_DARK_INK : DEFAULT_INK;
  const ink = sketchColorOverride ?? baseInk;

  if (isDark) {
    return {
      isDark: true,
      ink,
      paper: DEFAULT_DARK_PAPER,
      cardBg: DEFAULT_DARK_CARD_BG,
      shadow: "rgba(0, 0, 0, 0.45)",
      accent: DARK_SKETCH_COLORS.accent,
      accentFill: DARK_SKETCH_COLORS.accentFill,
      secondaryFill: DARK_SKETCH_COLORS.secondaryFill,
      info: DARK_SKETCH_COLORS.info,
      warning: DARK_SKETCH_COLORS.warning,
      error: DARK_SKETCH_COLORS.error,
      success: DARK_SKETCH_COLORS.success,
    };
  }

  return {
    isDark: false,
    ink,
    paper: DEFAULT_PAPER,
    cardBg: DEFAULT_PAPER,
    shadow: sketchColorOverride ?? DEFAULT_INK,
    accent: SKETCH_COLORS.accent,
    accentFill: SKETCH_COLORS.accentFill,
    secondaryFill: SKETCH_COLORS.secondaryFill,
    info: SKETCH_COLORS.info,
    warning: SKETCH_COLORS.warning,
    error: SKETCH_COLORS.error,
    success: SKETCH_COLORS.success,
  };
}

"use client";

import { useLayoutEffect, useRef, type CSSProperties } from "react";
import rough from "roughjs";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import {
  mergeSketchProps,
  readSketchCssVars,
  useSketchDefaults,
} from "../hooks/useSketchDefaults";
import { useElementSize } from "../hooks/useElementSize";
import {
  DEFAULT_INSET,
  toRoughOptions,
  type RoughSvgProps,
} from "../types";

/**
 * Absolutely-positioned SVG layer that draws a rough.js shape behind HTML content.
 * Parent must be `position: relative`.
 *
 * @example
 * <div style={{ position: "relative" }}>
 *   <RoughSvg roughness={2} sketchColor="#1f1d1a" />
 *   <span>Content</span>
 * </div>
 *
 * @see SketchBox
 */
/**
 * Low-level rough.js SVG overlay.
 *
 * @example
 * <RoughSvg />
 */
export function RoughSvg({
  shape = "rectangle",
  width: widthProp,
  height: heightProp,
  roughness,
  seed: seedProp,
  sketchColor,
  bowing,
  fillStyle,
  strokeWidth,
  fill,
  hachureGap,
  hachureAngle,
  fillWeight,
  inset = DEFAULT_INSET,
  path,
  className,
  style,
}: RoughSvgProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const measured = useElementSize(containerRef);
  const seed = useResolvedSeed(seedProp);
  const sketchDefaults = useSketchDefaults();

  const width = widthProp ?? measured.width;
  const height = heightProp ?? measured.height;

  useLayoutEffect(() => {
    const svg = svgRef.current;
    const container = containerRef.current;
    if (!svg || width < 2 || height < 2) return;

    while (svg.firstChild) svg.removeChild(svg.firstChild);

    const cssVars = readSketchCssVars(container);
    const merged = mergeSketchProps(
      {
        roughness,
        seed,
        sketchColor,
        bowing,
        fillStyle,
        strokeWidth,
        hachureGap,
        hachureAngle,
        fillWeight,
      },
      sketchDefaults,
      cssVars,
    );

    const rc = rough.svg(svg);
    const options = toRoughOptions({
      roughness: merged.roughness,
      seed,
      sketchColor: merged.sketchColor,
      bowing: merged.bowing,
      fillStyle: merged.fillStyle,
      strokeWidth: merged.strokeWidth,
      fill,
      hachureGap,
      hachureAngle,
      fillWeight,
    });

    const x = inset;
    const y = inset;
    const w = Math.max(1, width - inset * 2);
    const h = Math.max(1, height - inset * 2);

    let node: SVGGElement;
    switch (shape) {
      case "ellipse":
        node = rc.ellipse(width / 2, height / 2, w, h, options);
        break;
      case "line":
        node = rc.line(inset, height / 2, width - inset, height / 2, options);
        break;
      case "line-vertical":
        node = rc.line(width / 2, inset, width / 2, height - inset, options);
        break;
      case "path":
        if (!path) return;
        node = rc.path(path, options);
        break;
      default:
        node = rc.rectangle(x, y, w, h, options);
    }

    svg.appendChild(node);
  }, [
    width,
    height,
    shape,
    roughness,
    seed,
    sketchColor,
    bowing,
    fillStyle,
    strokeWidth,
    fill,
    hachureGap,
    hachureAngle,
    fillWeight,
    inset,
    path,
    sketchDefaults,
  ]);

  const overlayStyle: CSSProperties = {
    position: "absolute",
    inset: 0,
    width: "100%",
    height: "100%",
    pointerEvents: "none",
    overflow: "visible",
    zIndex: 0,
    ...style,
  };

  return (
    <div
      ref={containerRef}
      aria-hidden="true"
      className={className}
      style={overlayStyle}
    >
      <svg
        ref={svgRef}
        width="100%"
        height="100%"
        overflow="visible"
        style={{ display: "block" }}
      />
    </div>
  );
}

"use client";

import { useSketchDefaults } from "../hooks/useSketchDefaults";
import {
  forwardRef,
  useRef,
  type CSSProperties,
  type HTMLAttributes,
  type MutableRefObject,
  type ReactNode,
} from "react";
import {
  DRAW_IN_DURATION_MS,
  useAnimate,
  useDrawIn,
} from "../animations";
import { useSketchTheme } from "../hooks/useSketchTheme";
import type { FillStyle, RoughShape, SketchProps } from "../types";
import { assignRef, cn, doodleUiFontFamily } from "../utils";
import { RoughSvg } from "./RoughSvg";

/**
 * Props for {@link SketchBox}.
 */
export interface SketchBoxProps
  extends SketchProps, Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  /** Child content rendered above the sketch layer. */
  children?: ReactNode;
  /**
   * rough.js shape for the border.
   * @default "rectangle"
   */
  shape?: RoughShape;
  /**
   * Fill color inside the sketch shape.
   * @default undefined
   */
  fill?: string;
  /**
   * Pattern when `fill` is set. Defaults to solid when shadow/fill implied.
   * @default "solid" when fill is implied
   */
  fillStyle?: FillStyle;
  /**
   * Draws an offset duplicate shape as a drop shadow.
   * @default false
   */
  shadow?: boolean;
  /** Class name on the inner content wrapper. */
  contentClassName?: string;
  /** Inline styles on the inner content wrapper. */
  contentStyle?: CSSProperties;
  /**
   * Inset passed to {@link RoughSvg}.
   * @default undefined ({@link DEFAULT_INSET} on RoughSvg)
   */
  inset?: number;
  /**
   * SVG path when `shape` is `"path"`.
   * @default undefined
   */
  path?: string;
  /**
   * Sketch-in the border on mount. Defaults to the DoodleUIProvider value.
   * @default undefined (follow provider)
   */
  animate?: boolean;
  /**
   * Override the default 400ms draw-in duration.
   * @default 400 ({@link DRAW_IN_DURATION_MS})
   */
  drawInDuration?: number;
  /**
   * Replay draw-in when this value changes.
   * @default undefined
   */
  drawInKey?: unknown;
}

/**
 * Relative container that draws a {@link RoughSvg} border behind children.
 *
 * @example
 * <SketchBox roughness={2} shadow>
 *   <p>Notes</p>
 * </SketchBox>
 *
 * @see Card
 */
export const SketchBox = forwardRef<HTMLDivElement, SketchBoxProps>(
  function SketchBox(
    {
      children,
      className,
      style,
      contentClassName,
      contentStyle,
      shape = "rectangle",
      fill,
      fillStyle,
      shadow = false,
      roughness,
      seed,
      sketchColor,
      bowing,
      strokeWidth,
      hachureGap,
      hachureAngle,
      fillWeight,
      inset,
      path,
      animate,
      drawInDuration = DRAW_IN_DURATION_MS,
      drawInKey,
      ...rest
    },
    ref,
  ) {
    const { roughness: baseRoughness } = useSketchDefaults();
    const rootRef = useRef<HTMLDivElement>(null);
    const theme = useSketchTheme(sketchColor);
    const resolvedInk = sketchColor ?? theme.ink;
    const shouldAnimate = useAnimate(animate);
    useDrawIn(rootRef, drawInDuration, shouldAnimate, drawInKey);

    const hasExplicitFill = fill !== undefined;
    const resolvedFill = hasExplicitFill ? fill : (shadow ? theme.cardBg : undefined);
    const resolvedFillStyle: FillStyle = fillStyle ?? (resolvedFill ? "solid" : "solid");
    const isPatternedFill = Boolean(resolvedFill && resolvedFillStyle !== "solid");

    return (
      <div
        ref={(node) => {
          (rootRef as MutableRefObject<HTMLDivElement | null>).current = node;
          assignRef(ref, node);
        }}
        className={cn(className)}
        style={{ position: "relative", ...style }}
        {...rest}
      >
        {shadow ? (
          <RoughSvg
            shape={shape}
            roughness={(roughness ?? baseRoughness) + 0.35}
            seed={seed}
            sketchColor={theme.isDark ? "rgba(0, 0, 0, 0.45)" : resolvedInk}
            bowing={bowing}
            fillStyle="hachure"
            fill={theme.isDark ? theme.shadow : (resolvedInk ?? theme.ink)}
            strokeWidth={1}
            hachureGap={8}
            inset={inset}
            style={{
              transform: "translate(5px, 6px)",
              opacity: theme.isDark ? 0.35 : 0.16,
            }}
          />
        ) : null}

        {isPatternedFill ? (
          <RoughSvg
            shape={shape}
            roughness={roughness}
            seed={seed}
            sketchColor="transparent"
            bowing={bowing}
            fillStyle="solid"
            fill={theme.cardBg}
            strokeWidth={0}
            inset={inset}
          />
        ) : null}

        <RoughSvg
          shape={shape}
          roughness={roughness}
          seed={seed}
          sketchColor={resolvedInk}
          bowing={bowing}
          fillStyle={resolvedFill ? resolvedFillStyle : undefined}
          fill={resolvedFill}
          strokeWidth={strokeWidth}
          hachureGap={hachureGap ?? (isPatternedFill ? 10 : undefined)}
          hachureAngle={hachureAngle}
          fillWeight={fillWeight ?? (isPatternedFill ? 0.9 : undefined)}
          inset={inset}
          path={path}
        />
        <div
          className={contentClassName}
          style={{
            position: "relative",
            zIndex: 1,
            fontFamily: doodleUiFontFamily,
            color: resolvedInk,
            ...contentStyle,
          }}
        >
          {children}
        </div>
      </div>
    );
  },
);

"use client";

import {
  createContext,
  forwardRef,
  useContext,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { AnimatePresence, motion, type Variants } from "framer-motion";
import { useAnimate } from "../animations";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { SketchBox } from "../primitives/SketchBox";
import type { SketchProps } from "../types";
import { cn, doodleUiFontFamily, doodleUiFontWeight } from "../utils";

export type SlidingPanelSide = "top" | "right" | "bottom" | "left";

interface SlidingPanelSketchContextValue extends SketchProps {
  resolvedSeed: number;
  ink: string;
  paper: string;
  isDark: boolean;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
  open: boolean;
  side: SlidingPanelSide;
}

const SlidingPanelSketchContext =
  createContext<SlidingPanelSketchContextValue | null>(null);

export function useSlidingPanelSketch(): SlidingPanelSketchContextValue {
  const ctx = useContext(SlidingPanelSketchContext);
  if (!ctx) {
    throw new Error("Sliding panel parts must be used inside the panel root.");
  }
  return ctx;
}

/**
 * Props for {@link SlidingPanelRoot}.
 */
export interface SlidingPanelRootProps
  extends Omit<DialogPrimitive.DialogProps, "children">,
    SketchProps {
  children?: ReactNode;
  side?: SlidingPanelSide;
  fill?: string;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

export function SlidingPanelRoot({
  children,
  open,
  defaultOpen,
  onOpenChange,
  side = "right",
  fill,
  roughness,
  seed,
  sketchColor,
  bowing,
  fillStyle,
  strokeWidth,
  hachureGap,
  hachureAngle,
  fillWeight,
  animate,
  ...rest
}: SlidingPanelRootProps) {
  const resolvedSeed = useResolvedSeed(seed);
  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;
  const [uncontrolled, setUncontrolled] = useState(defaultOpen === true);
  const isOpen = open ?? uncontrolled;

  return (
    <SlidingPanelSketchContext.Provider
      value={{
        roughness,
        seed: resolvedSeed,
        sketchColor,
        bowing,
        fillStyle,
        strokeWidth,
        hachureGap,
        hachureAngle,
        fillWeight,
        resolvedSeed,
        ink,
        paper: fill ?? theme.paper,
        isDark: theme.isDark,
        animate,
        open: isOpen,
        side,
      }}
    >
      <DialogPrimitive.Root
        open={isOpen}
        onOpenChange={(next) => {
          setUncontrolled(next);
          onOpenChange?.(next);
        }}
        {...rest}
      >
        {children}
      </DialogPrimitive.Root>
    </SlidingPanelSketchContext.Provider>
  );
}

export const SlidingPanelTrigger = DialogPrimitive.Trigger;
export const SlidingPanelClose = DialogPrimitive.Close;
export const SlidingPanelPortal = DialogPrimitive.Portal;

function slideVariants(side: SlidingPanelSide, shouldAnimate: boolean): Variants {
  if (!shouldAnimate) {
    return { hidden: {}, visible: {} };
  }
  const offset = 420;
  const hidden =
    side === "left"
      ? { x: -offset }
      : side === "right"
        ? { x: offset }
        : side === "top"
          ? { y: -offset }
          : { y: offset };
  return {
    hidden: { ...hidden, opacity: 0.85 },
    visible: { x: 0, y: 0, opacity: 1 },
  };
}

function panelPosition(side: SlidingPanelSide): CSSProperties {
  switch (side) {
    case "left":
      return {
        top: 0,
        bottom: 0,
        left: 0,
        width: "min(420px, 100vw)",
      };
    case "right":
      return {
        top: 0,
        bottom: 0,
        right: 0,
        width: "min(420px, 100vw)",
      };
    case "top":
      return {
        top: 0,
        left: 0,
        right: 0,
        height: "min(420px, 90vh)",
      };
    default:
      return {
        bottom: 0,
        left: 0,
        right: 0,
        height: "min(420px, 90vh)",
      };
  }
}

/**
 * Props for {@link SlidingPanelOverlay}.
 */
export interface SlidingPanelOverlayProps
  extends Omit<DialogPrimitive.DialogOverlayProps, "asChild" | "forceMount"> {}

export const SlidingPanelOverlay = forwardRef<
  HTMLDivElement,
  SlidingPanelOverlayProps
>(function SlidingPanelOverlay({ style, ...rest }, ref) {
  const sketch = useSlidingPanelSketch();
  const shouldAnimate = useAnimate(sketch.animate);

  return (
    <DialogPrimitive.Overlay ref={ref} asChild forceMount {...rest}>
      <motion.div
        initial={shouldAnimate ? { opacity: 0 } : false}
        animate={{ opacity: 1 }}
        exit={shouldAnimate ? { opacity: 0 } : undefined}
        transition={
          shouldAnimate ? { duration: 0.22, ease: "easeOut" } : { duration: 0 }
        }
        style={{
          position: "fixed",
          inset: 0,
          background: sketch.isDark ? "rgba(0, 0, 0, 0.65)" : "rgba(31, 29, 26, 0.38)",
          zIndex: 70,
          ...style,
        }}
      />
    </DialogPrimitive.Overlay>
  );
});

/**
 * Props for {@link SlidingPanelContent}.
 */
export interface SlidingPanelContentProps
  extends Omit<DialogPrimitive.DialogContentProps, "asChild" | "forceMount"> {
  children?: ReactNode;
  contentStyle?: CSSProperties;
  fill?: string;
  /** Extra chrome above panel content (e.g. drawer handle). */
  chrome?: ReactNode;
}

export const SlidingPanelContent = forwardRef<
  HTMLDivElement,
  SlidingPanelContentProps
>(function SlidingPanelContent(
  { className, style, contentStyle, fill, children, chrome, ...rest },
  ref,
) {
  const sketch = useSlidingPanelSketch();
  const shouldAnimate = useAnimate(sketch.animate);
  const variants = slideVariants(sketch.side, shouldAnimate);

  return (
    <AnimatePresence>
      {sketch.open ? (
        <DialogPrimitive.Portal forceMount>
          <SlidingPanelOverlay />
          <DialogPrimitive.Content ref={ref} asChild forceMount {...rest}>
            <motion.div
              className={cn(className)}
              initial={shouldAnimate ? "hidden" : false}
              animate="visible"
              exit={shouldAnimate ? "hidden" : undefined}
              variants={variants}
              transition={
                shouldAnimate
                  ? { duration: 0.28, ease: "easeOut" }
                  : { duration: 0 }
              }
              style={{
                position: "fixed",
                zIndex: 80,
                outline: "none",
                pointerEvents: "auto",
                ...panelPosition(sketch.side),
                ...style,
              }}
            >
              <SketchBox
                roughness={sketch.roughness}
                seed={sketch.resolvedSeed}
                sketchColor={sketch.ink}
                bowing={sketch.bowing}
                fillStyle={sketch.fillStyle ?? "solid"}
                fill={fill ?? sketch.paper}
                strokeWidth={sketch.strokeWidth ?? 2}
                hachureGap={sketch.hachureGap}
                hachureAngle={sketch.hachureAngle}
                fillWeight={sketch.fillWeight}
                animate={sketch.animate}
                contentStyle={{
                  padding: 20,
                  height: "100%",
                  boxSizing: "border-box",
                  display: "flex",
                  flexDirection: "column",
                  color: sketch.ink,
                  ...contentStyle,
                }}
                style={{ height: "100%" }}
              >
                {chrome}
                {children}
              </SketchBox>
            </motion.div>
          </DialogPrimitive.Content>
        </DialogPrimitive.Portal>
      ) : null}
    </AnimatePresence>
  );
});

/**
 * Props for {@link SlidingPanelHeader}.
 */
export interface SlidingPanelHeaderProps {
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

export function SlidingPanelHeader({
