"use client";

import { useSketchDefaults } from "../hooks/useSketchDefaults";
import {
  createContext,
  forwardRef,
  useContext,
  useState,
  type ComponentPropsWithoutRef,
  type CSSProperties,
  type ReactNode,
} from "react";
import * as AccordionPrimitive from "@radix-ui/react-accordion";
import { RoughSvg } from "../primitives/RoughSvg";
import type { SketchProps } from "../types";
import { cn, doodleUiFontFamily, doodleUiFontWeight } from "../utils";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { deriveSeed } from "../utils";

const CHEVRON_PATH = "M 6 4 L 12 10 L 6 16";

interface AccordionSketchContextValue extends SketchProps {
  resolvedSeed: number;
  ink: string;
  openValue: string | string[] | undefined;
}

const AccordionSketchContext =
  createContext<AccordionSketchContextValue | null>(null);

function useAccordionSketch(): AccordionSketchContextValue {
  const ctx = useContext(AccordionSketchContext);
  if (!ctx) {
    throw new Error("Accordion parts must be used inside <Accordion>.");
  }
  return ctx;
}

const AccordionItemContext = createContext<string>("");

/**
 * Props for {@link Accordion}.
 */
export interface AccordionProps extends SketchProps {
  type?: "single" | "multiple";
  collapsible?: boolean;
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  disabled?: boolean;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
}

/**
 * Expandable sections with chevron sketch.
 *
 * @example
 * <Accordion />
 */
export const Accordion = forwardRef<HTMLDivElement, AccordionProps>(
  function Accordion(
    {
      className,
      style,
      children,
      type = "single",
      collapsible = true,
      value,
      defaultValue,
      onValueChange,
      disabled,
      roughness,
      seed,
      sketchColor,
      bowing,
      fillStyle,
      strokeWidth,
      hachureGap,
      hachureAngle,
      fillWeight,
    },
    ref,
  ) {
    const resolvedSeed = useResolvedSeed(seed);
    const theme = useSketchTheme(sketchColor);
    const ink = sketchColor ?? theme.ink;
    const [uncontrolled, setUncontrolled] = useState<
      string | string[] | undefined
    >(defaultValue ?? (type === "multiple" ? [] : undefined));
    const openValue = value ?? uncontrolled;

    const sketchValue: AccordionSketchContextValue = {
      roughness,
      seed: resolvedSeed,
      sketchColor: ink,
      bowing,
      fillStyle,
      strokeWidth,
      hachureGap,
      hachureAngle,
      fillWeight,
      resolvedSeed,
      ink,
      openValue,
    };

    function handleChange(next: string | string[]) {
      setUncontrolled(next);
      onValueChange?.(next);
    }

    const root =
      type === "multiple" ? (
        <AccordionPrimitive.Root
          ref={ref}
          type="multiple"
          disabled={disabled}
          className={cn(className)}
          style={style}
          value={openValue as string[] | undefined}
          defaultValue={defaultValue as string[] | undefined}
          onValueChange={handleChange}
        >
          {children}
        </AccordionPrimitive.Root>
      ) : (
        <AccordionPrimitive.Root
          ref={ref}
          type="single"
          collapsible={collapsible}
          disabled={disabled}
          className={cn(className)}
          style={style}
          value={openValue as string | undefined}
          defaultValue={defaultValue as string | undefined}
          onValueChange={handleChange}
        >
          {children}
        </AccordionPrimitive.Root>
      );

    return (
      <AccordionSketchContext.Provider value={sketchValue}>
        {root}
      </AccordionSketchContext.Provider>
    );
  },
);

/**
 * Props for {@link AccordionItem}.
 */
export interface AccordionItemProps
  extends Omit<
    ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>,
    "asChild"
  > {}

export const AccordionItem = forwardRef<HTMLDivElement, AccordionItemProps>(
  function AccordionItem({ className, style, children, value, ...rest }, ref) {
    const { roughness: baseRoughness } = useSketchDefaults();
    const sketch = useAccordionSketch();

    return (
      <AccordionItemContext.Provider value={value}>
        <AccordionPrimitive.Item
          ref={ref}
          value={value}
          className={cn(className)}
          style={{ position: "relative", ...style }}
          {...rest}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: -6,
              height: 12,
              pointerEvents: "none",
            }}
          >
            <RoughSvg
              shape="line"
              roughness={(sketch.roughness ?? baseRoughness) + 0.25}
              seed={deriveSeed(sketch.resolvedSeed, `div-${value}`)}
              sketchColor={sketch.ink}
              bowing={sketch.bowing ?? 1.8}
              strokeWidth={sketch.strokeWidth ?? 1.4}
              inset={2}
            />
          </div>
          {children}
        </AccordionPrimitive.Item>
      </AccordionItemContext.Provider>
    );
  },
);

/**
 * Props for {@link AccordionTrigger}.
 */
export interface AccordionTriggerProps
  extends Omit<
    ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>,
    "asChild"
  > {
  children?: ReactNode;
}

export const AccordionTrigger = forwardRef<
  HTMLButtonElement,
  AccordionTriggerProps
>(function AccordionTrigger({ className, style, children, ...rest }, ref) {
  const { roughness: baseRoughness } = useSketchDefaults();
  const sketch = useAccordionSketch();
  const itemValue = useContext(AccordionItemContext);
  const open = Array.isArray(sketch.openValue)
    ? sketch.openValue.includes(itemValue)
    : sketch.openValue === itemValue;

  return (
    <AccordionPrimitive.Header asChild>
      <h3 style={{ margin: 0 }}>
        <AccordionPrimitive.Trigger
          ref={ref}
          className={cn(className)}
          style={{
            display: "flex",
            width: "100%",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 12,
            padding: "12px 4px",
            border: "none",
            background: "transparent",
            cursor: "pointer",
            fontFamily: doodleUiFontFamily,
            fontSize: 15,
            fontWeight: doodleUiFontWeight(600),
            color: sketch.ink,
            textAlign: "left",
            outline: "none",
            ...style,
          }}
          {...rest}
        >
          <span>{children}</span>
          <span
            style={{
              position: "relative",
              width: 18,
              height: 18,
              flexShrink: 0,
              transform: open ? "rotate(90deg)" : "rotate(0deg)",
              transition: "transform 180ms ease",
            }}
          >
            <RoughSvg
              shape="path"
              path={CHEVRON_PATH}
              roughness={(sketch.roughness ?? baseRoughness) * 0.7}
              seed={deriveSeed(sketch.resolvedSeed, `chevron-${itemValue}`)}
              sketchColor={sketch.ink}
              bowing={sketch.bowing}
              strokeWidth={(sketch.strokeWidth ?? 1.6) + 0.2}
              inset={0}
            />
          </span>
        </AccordionPrimitive.Trigger>
      </h3>
    </AccordionPrimitive.Header>
  );
});

/**
 * Props for {@link AccordionContent}.
 */
export interface AccordionContentProps
  extends Omit<
    ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>,
    "asChild"
  > {}

export const AccordionContent = forwardRef<
  HTMLDivElement,
  AccordionContentProps
>(function AccordionContent({ className, style, children, ...rest }, ref) {
  const sketch = useAccordionSketch();
  return (
    <AccordionPrimitive.Content
      ref={ref}
      className={cn(className)}
      style={{
        padding: "0 4px 14px",
        fontFamily: doodleUiFontFamily,
        fontSize: 14,
        lineHeight: 1.5,
        color: sketch.ink,
        ...style,
      }}
      {...rest}
    >
      {children}
    </AccordionPrimitive.Content>
  );
});

"use client";

import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import { DRAW_IN_ALERT_MS } from "../animations";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { SketchBox } from "../primitives/SketchBox";
import type { SketchProps } from "../types";
import { cn, doodleUiFontWeight } from "../utils";

export type AlertVariant = "info" | "warning" | "error" | "success";

/**
 * Props for {@link Alert}.
 */
export interface AlertProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "color" | "title">,
    SketchProps {
  variant?: AlertVariant;
  title?: ReactNode;
  fill?: string;
  /**
   * Draw-in the border on mount (~200ms). Defaults to the DoodleUIProvider value (true).
   */
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

const LIGHT_VARIANT_FILL: Record<AlertVariant, string> = {
  info: "#d2deec",
  warning: "#f3e2c0",
  error: "#f3d0cc",
  success: "#d3e8dc",
};

const DARK_VARIANT_FILL: Record<AlertVariant, string> = {
  info: "rgba(96, 165, 250, 0.16)",
  warning: "rgba(251, 191, 36, 0.16)",
  error: "rgba(248, 113, 113, 0.16)",
  success: "rgba(52, 211, 153, 0.16)",
};

/**
 * Color-coded callout with sketch framing.
 *
 * @example
 * <Alert />
 */
export const Alert = forwardRef<HTMLDivElement, AlertProps>(function Alert(
  {
    children,
    className,
    style,
    variant = "info",
    title,
    fill,
    roughness,
    seed,
    sketchColor,
    bowing,
    fillStyle,
    strokeWidth,
    hachureGap,
    hachureAngle,
    fillWeight,
    role = "status",
    animate,
    ...rest
  },
  ref,
) {
  const theme = useSketchTheme(sketchColor);
  const color = sketchColor ?? theme[variant];
  const defaultFill = theme.isDark ? DARK_VARIANT_FILL[variant] : LIGHT_VARIANT_FILL[variant];
  const resolvedFill = fill ?? defaultFill;

  return (
    <SketchBox
      ref={ref}
      role={role}
      className={cn(className)}
      style={{ color, ...style }}
      contentStyle={{ padding: "12px 16px", color: theme.ink }}
      roughness={roughness}
      seed={seed}
      sketchColor={color}
      bowing={bowing}
      fillStyle={fillStyle ?? "hachure"}
      fill={resolvedFill}
      strokeWidth={strokeWidth}
      hachureGap={hachureGap ?? 9}
      hachureAngle={hachureAngle}
      fillWeight={fillWeight ?? 0.85}
      animate={animate}
      drawInDuration={DRAW_IN_ALERT_MS}
      {...rest}
    >
      {title ? (
        <div
          style={{
            fontWeight: doodleUiFontWeight(700),
            marginBottom: 4,
            fontSize: 15,
            color,
          }}
        >
          {title}
        </div>
      ) : null}
      <div style={{ fontSize: 14, lineHeight: 1.5, color: theme.ink }}>
        {children}
      </div>
    </SketchBox>
  );
});

"use client";

import {
  createContext,
  forwardRef,
  useContext,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import * as AlertDialogPrimitive from "@radix-ui/react-alert-dialog";
import { AnimatePresence, motion } from "framer-motion";
import { useAnimate } from "../animations";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { SketchBox } from "../primitives/SketchBox";
import type { SketchProps } from "../types";
import { cn, doodleUiFontFamily, doodleUiFontWeight } from "../utils";
import { Button } from "./Button";

interface AlertDialogSketchContextValue extends SketchProps {
  resolvedSeed: number;
  ink: string;
  paper: string;
  isDark: boolean;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
  open: boolean;
}

const AlertDialogSketchContext =
  createContext<AlertDialogSketchContextValue | null>(null);

function useAlertDialogSketch(): AlertDialogSketchContextValue {
  const ctx = useContext(AlertDialogSketchContext);
  if (!ctx) {
    throw new Error(
      "AlertDialog parts must be used inside <AlertDialog>.",
    );
  }
  return ctx;
}

/**
 * Props for {@link AlertDialog}.
 */
export interface AlertDialogProps
  extends Omit<AlertDialogPrimitive.AlertDialogProps, "children">,
    SketchProps {
  children?: ReactNode;
  fill?: string;
  /**
   * Backdrop fade, panel enter/exit, and border draw-in on open.
   * Defaults to the DoodleUIProvider value (true).
   */
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

/**
 * Confirm / destructive-action variant of `Dialog`. Same composable shape,
 * but Radix's alert dialog primitive requires an explicit action — there is
 * no dismiss-on-outside-click or Escape by default, and `AlertDialogAction`
 * / `AlertDialogCancel` give the confirm button visual emphasis.
 */
/**
 * AlertDialog doodle-ui component.
 *
 * @example
 * <AlertDialog />
 */
export function AlertDialog({
  children,
  open,
  defaultOpen,
  onOpenChange,
  fill,
  roughness,
  seed,
  sketchColor,
  bowing,
  fillStyle,
  strokeWidth,
  hachureGap,
  hachureAngle,
  fillWeight,
  animate,
  ...rest
}: AlertDialogProps) {
  const resolvedSeed = useResolvedSeed(seed);
  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;
  const [uncontrolled, setUncontrolled] = useState(defaultOpen === true);
  const isOpen = open ?? uncontrolled;

  return (
    <AlertDialogSketchContext.Provider
      value={{
        roughness,
        seed: resolvedSeed,
        sketchColor,
        bowing,
        fillStyle,
        strokeWidth,
        hachureGap,
        hachureAngle,
        fillWeight,
        resolvedSeed,
        ink,
        paper: fill ?? theme.paper,
        isDark: theme.isDark,
        animate,
        open: isOpen,
      }}
    >
      <AlertDialogPrimitive.Root
        open={isOpen}
        onOpenChange={(next) => {
          setUncontrolled(next);
          onOpenChange?.(next);
        }}
        {...rest}
      >
        {children}
      </AlertDialogPrimitive.Root>
    </AlertDialogSketchContext.Provider>
  );
}

export const AlertDialogTrigger = AlertDialogPrimitive.Trigger;
export const AlertDialogPortal = AlertDialogPrimitive.Portal;

/**
 * Props for {@link AlertDialogOverlay}.
 */
export interface AlertDialogOverlayProps
  extends Omit<
    AlertDialogPrimitive.AlertDialogOverlayProps,
    "asChild" | "forceMount"
  > {}

export const AlertDialogOverlay = forwardRef<
  HTMLDivElement,
  AlertDialogOverlayProps
>(function AlertDialogOverlay({ style, ...rest }, ref) {
  const sketch = useAlertDialogSketch();
  const shouldAnimate = useAnimate(sketch.animate);

  return (
    <AlertDialogPrimitive.Overlay ref={ref} asChild forceMount {...rest}>
      <motion.div
        initial={shouldAnimate ? { opacity: 0 } : false}
        animate={{ opacity: 1 }}
        exit={shouldAnimate ? { opacity: 0 } : undefined}
        transition={
          shouldAnimate ? { duration: 0.2, ease: "easeOut" } : { duration: 0 }
        }
        style={{
          position: "fixed",
          inset: 0,
          background: sketch.isDark ? "rgba(0, 0, 0, 0.65)" : "rgba(31, 29, 26, 0.38)",
          zIndex: 70,
          ...style,
        }}
      />
    </AlertDialogPrimitive.Overlay>
  );
});

/**
 * Props for {@link AlertDialogContent}.
 */
export interface AlertDialogContentProps
  extends Omit<
    AlertDialogPrimitive.AlertDialogContentProps,
    "asChild" | "forceMount"
  > {
  children?: ReactNode;
  fill?: string;
  contentStyle?: CSSProperties;
}

export const AlertDialogContent = forwardRef<
  HTMLDivElement,
  AlertDialogContentProps
>(function AlertDialogContent(
  { className, style, contentStyle, fill, children, ...rest },
  ref,
) {
  const sketch = useAlertDialogSketch();
  const shouldAnimate = useAnimate(sketch.animate);

  return (
    <AnimatePresence>
      {sketch.open ? (
        <AlertDialogPrimitive.Portal forceMount>
          <AlertDialogOverlay />
          <div
            style={{
              position: "fixed",
              inset: 0,
              zIndex: 80,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              pointerEvents: "none",
              padding: 16,
            }}
          >
            <AlertDialogPrimitive.Content ref={ref} asChild forceMount {...rest}>
              <motion.div
                className={cn(className)}
                initial={
                  shouldAnimate ? { opacity: 0, scale: 0.96, y: 10 } : false
                }
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={
                  shouldAnimate ? { opacity: 0, scale: 0.96, y: 8 } : undefined
                }
                transition={
                  shouldAnimate
                    ? { duration: 0.22, ease: "easeOut" }
                    : { duration: 0 }
                }
                style={{
                  width: "min(420px, calc(100vw - 32px))",
                  outline: "none",
                  pointerEvents: "auto",
                  color: sketch.ink,
                  ...style,
                }}
              >
                <SketchBox
                  roughness={sketch.roughness}
                  seed={sketch.resolvedSeed}
                  sketchColor={sketch.ink}
                  bowing={sketch.bowing}
                  fillStyle={sketch.fillStyle ?? "solid"}
                  fill={fill ?? sketch.paper}
                  strokeWidth={sketch.strokeWidth ?? 2}
                  hachureGap={sketch.hachureGap}
                  hachureAngle={sketch.hachureAngle}
                  fillWeight={sketch.fillWeight}
                  animate={sketch.animate}
                  contentStyle={{ padding: 20, color: sketch.ink, ...contentStyle }}
                >
                  {children}
                </SketchBox>
              </motion.div>
            </AlertDialogPrimitive.Content>
          </div>
        </AlertDialogPrimitive.Portal>
      ) : null}
    </AnimatePresence>
  );
});

/**
 * Props for {@link AlertDialogHeader}.
 */
export interface AlertDialogHeaderProps {
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

export function AlertDialogHeader({
  children,
  className,
  style,
}: AlertDialogHeaderProps) {
  return (
    <div
      className={cn(className)}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 6,
        marginBottom: 12,
        ...style,
      }}
    >
      {children}
    </div>
  );
}

/**
 * Props for {@link AlertDialogFooter}.
 */
export interface AlertDialogFooterProps {
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

export function AlertDialogFooter({
  children,
  className,
  style,
}: AlertDialogFooterProps) {
  return (
    <div
      className={cn(className)}
      style={{
        display: "flex",
        justifyContent: "flex-end",
        gap: 8,
        marginTop: 16,
        ...style,
      }}
    >
      {children}
    </div>
  );
}

/**
 * Props for {@link AlertDialogTitle}.
 */
export interface AlertDialogTitleProps
  extends Omit<AlertDialogPrimitive.AlertDialogTitleProps, "asChild"> {}

export const AlertDialogTitle = forwardRef<
  HTMLHeadingElement,
  AlertDialogTitleProps
>(function AlertDialogTitle({ style, ...rest }, ref) {
  const sketch = useAlertDialogSketch();
  return (
    <AlertDialogPrimitive.Title
      ref={ref}
      style={{
        margin: 0,
        fontSize: 18,
        fontWeight: doodleUiFontWeight(700),
        fontFamily: doodleUiFontFamily,
        color: sketch.ink,
        ...style,
      }}
      {...rest}
    />
  );
});

/**
 * Props for {@link AlertDialogDescription}.
 */
export interface AlertDialogDescriptionProps
  extends Omit<AlertDialogPrimitive.AlertDialogDescriptionProps, "asChild"> {}

export const AlertDialogDescription = forwardRef<
  HTMLParagraphElement,
  AlertDialogDescriptionProps
>(function AlertDialogDescription({ style, ...rest }, ref) {
  const sketch = useAlertDialogSketch();
  return (
    <AlertDialogPrimitive.Description
      ref={ref}
      style={{
        margin: 0,
        fontSize: 14,
        lineHeight: 1.5,
        fontFamily: doodleUiFontFamily,
        color: sketch.ink,
        opacity: 0.8,
        ...style,
      }}
      {...rest}
    />
  );
});

/**
 * Props for {@link AlertDialogAction}.
 */
export interface AlertDialogActionProps
  extends Omit<AlertDialogPrimitive.AlertDialogActionProps, "asChild"> {}

export const AlertDialogAction = forwardRef<
  HTMLButtonElement,
  AlertDialogActionProps
>(function AlertDialogAction({ children, ...rest }, ref) {
  const sketch = useAlertDialogSketch();
  return (
    <AlertDialogPrimitive.Action asChild>
      <Button
        ref={ref}
        variant="primary"
        sketchColor={sketch.sketchColor}
        roughness={sketch.roughness}
        seed={sketch.resolvedSeed}
        bowing={sketch.bowing}
        animate={sketch.animate}
        {...rest}
      >
        {children}
      </Button>
    </AlertDialogPrimitive.Action>
  );
});

/**
 * Props for {@link AlertDialogCancel}.
 */
export interface AlertDialogCancelProps
  extends Omit<AlertDialogPrimitive.AlertDialogCancelProps, "asChild"> {}

export const AlertDialogCancel = forwardRef<
  HTMLButtonElement,
  AlertDialogCancelProps
>(function AlertDialogCancel({ children, ...rest }, ref) {
  const sketch = useAlertDialogSketch();
  return (
    <AlertDialogPrimitive.Cancel asChild>
      <Button
        ref={ref}
        variant="outline"
        sketchColor={sketch.sketchColor}
        roughness={sketch.roughness}
        seed={sketch.resolvedSeed}
        bowing={sketch.bowing}
        animate={sketch.animate}
        {...rest}
      >
        {children}
      </Button>
    </AlertDialogPrimitive.Cancel>
  );
});

"use client";

import * as AspectRatioPrimitive from "@radix-ui/react-aspect-ratio";
import type { CSSProperties, ReactNode } from "react";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { SketchBox } from "../primitives/SketchBox";
import type { SketchProps } from "../types";
import { cn } from "../utils";

/**
 * Props for {@link AspectRatio}.
 */
export interface AspectRatioProps extends SketchProps {
  ratio?: number;
  /** Wrap content in a hand-drawn frame. Default false — ratio box only. */
  bordered?: boolean;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
  fill?: string;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

/**
 * Fixed aspect ratio container.
 *
 * @example
 * <AspectRatio />
 */
export function AspectRatio({
  ratio = 16 / 9,
  bordered = false,
  className,
  style,
  children,
  fill,
  roughness,
  seed,
  sketchColor,
  bowing,
  fillStyle,
  strokeWidth,
  hachureGap,
  hachureAngle,
  fillWeight,
  animate,
}: AspectRatioProps) {
  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;

  const inner = (
    <AspectRatioPrimitive.Root
      ratio={ratio}
      className={cn(className)}
      style={{
        width: "100%",
        overflow: "hidden",
        color: ink,
        ...style,
      }}
    >
      <div style={{ width: "100%", height: "100%" }}>{children}</div>
    </AspectRatioPrimitive.Root>
  );

  if (!bordered) {
    return inner;
  }

  return (
    <SketchBox
      className={cn(className)}
      style={{ width: "100%", color: ink, ...style }}
      contentStyle={{ padding: 0, width: "100%", color: ink }}
      fill={fill ?? theme.paper}
      fillStyle={fillStyle ?? "solid"}
      hachureGap={hachureGap}
      hachureAngle={hachureAngle}
      fillWeight={fillWeight}
      roughness={roughness}
      seed={seed}
      sketchColor={ink}
      bowing={bowing}
      strokeWidth={strokeWidth}
      animate={animate}
    >
      <AspectRatioPrimitive.Root ratio={ratio} style={{ width: "100%" }}>
        <div style={{ width: "100%", height: "100%" }}>{children}</div>
      </AspectRatioPrimitive.Root>
    </SketchBox>
  );
}

