  }
  return ctx;
}

export type CarouselOptions = Parameters<typeof useEmblaCarousel>[0];

/**
 * Props for {@link Carousel}.
 */
export interface CarouselProps extends SketchProps {
  opts?: CarouselOptions;
  plugins?: Parameters<typeof useEmblaCarousel>[1];
  orientation?: "horizontal" | "vertical";
  bordered?: boolean;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
  setApi?: (api: CarouselApi) => void;
  fill?: string;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

/**
 * Slide carousel with sketch navigation arrows.
 *
 * @example
 * <Carousel />
 */
export function Carousel({
  opts,
  plugins,
  orientation = "horizontal",
  bordered = false,
  className,
  style,
  children,
  setApi,
  fill,
  roughness,
  seed,
  sketchColor,
  bowing,
  strokeWidth,
  fillStyle,
  hachureGap,
  hachureAngle,
  fillWeight,
  animate,
}: CarouselProps) {
  const [emblaRef, api] = useEmblaCarousel(
    {
      ...opts,
      axis: orientation === "horizontal" ? "x" : "y",
    },
    plugins,
  );
  const [canScrollPrev, setCanScrollPrev] = useState(false);
  const [canScrollNext, setCanScrollNext] = useState(false);

  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;
  const paper = fill ?? theme.paper;

  const scrollPrev = useCallback(() => api?.scrollPrev(), [api]);
  const scrollNext = useCallback(() => api?.scrollNext(), [api]);

  const onSelect = useCallback(() => {
    if (!api) return;
    setCanScrollPrev(api.canScrollPrev());
    setCanScrollNext(api.canScrollNext());
  }, [api]);

  useEffect(() => {
    if (!api) return;
    setApi?.(api);
    onSelect();
    api.on("reInit", onSelect);
    api.on("select", onSelect);
    return () => {
      api.off("reInit", onSelect);
      api.off("select", onSelect);
    };
  }, [api, onSelect, setApi]);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (orientation === "horizontal") {
        if (event.key === "ArrowLeft") {
          event.preventDefault();
          scrollPrev();
        } else if (event.key === "ArrowRight") {
          event.preventDefault();
          scrollNext();
        }
      } else if (event.key === "ArrowUp") {
        event.preventDefault();
        scrollPrev();
      } else if (event.key === "ArrowDown") {
        event.preventDefault();
        scrollNext();
      }
    },
    [orientation, scrollPrev, scrollNext],
  );

  const value: CarouselContextValue = {
    emblaRef,
    api,
    scrollPrev,
    scrollNext,
    canScrollPrev,
    canScrollNext,
    orientation,
    sketch: {
      roughness,
      seed,
      sketchColor: ink,
      bowing,
      strokeWidth,
      fillStyle,
      hachureGap,
      hachureAngle,
      fillWeight,
      animate,
      paper,
      ink,
    },
    bordered,
  };

  return (
    <CarouselContext.Provider value={value}>
      <div
        className={cn(className)}
        role="region"
        aria-roledescription="carousel"
        tabIndex={0}
        onKeyDown={handleKeyDown}
        style={{
          position: "relative",
          width: "100%",
          outline: "none",
          color: ink,
          ...style,
        }}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  );
}

/**
 * Props for {@link CarouselContent}.
 */
export interface CarouselContentProps extends HTMLAttributes<HTMLDivElement> {}

export const CarouselContent = forwardRef<HTMLDivElement, CarouselContentProps>(
  function CarouselContent({ className, style, children, ...rest }, ref) {
    const { emblaRef, orientation, bordered, sketch } = useCarousel();
    const gap = 16;

    const viewport = (
      <div ref={emblaRef} style={{ overflow: "hidden" }}>
        <div
          ref={ref}
          className={cn(className)}
          style={{
            display: "flex",
            flexDirection: orientation === "vertical" ? "column" : "row",
            marginLeft: orientation === "horizontal" ? -gap : 0,
            marginTop: orientation === "vertical" ? -gap : 0,
            ...style,
          }}
          {...rest}
        >
          {children}
        </div>
      </div>
    );

    if (!bordered) {
      return viewport;
    }

    return (
      <SketchBox
        fill={sketch.paper}
        fillStyle={sketch.fillStyle ?? "solid"}
        roughness={sketch.roughness}
        seed={sketch.seed}
        sketchColor={sketch.sketchColor}
        bowing={sketch.bowing}
        strokeWidth={sketch.strokeWidth}
        hachureGap={sketch.hachureGap}
        hachureAngle={sketch.hachureAngle}
        fillWeight={sketch.fillWeight}
        animate={sketch.animate}
        contentStyle={{ padding: 8, color: sketch.ink }}
      >
        {viewport}
      </SketchBox>
    );
  },
);

/**
 * Props for {@link CarouselItem}.
 */
export interface CarouselItemProps extends HTMLAttributes<HTMLDivElement> {}

export const CarouselItem = forwardRef<HTMLDivElement, CarouselItemProps>(
  function CarouselItem({ className, style, children, ...rest }, ref) {
    const { orientation } = useCarousel();
