/**
 * Props for {@link Checkbox}.
 */
export interface CheckboxProps
  extends Omit<CheckboxPrimitive.CheckboxProps, "asChild">,
    SketchProps {
  /** Visible label beside the control. */
  label?: ReactNode;
  fill?: string;
  /**
   * Draw-in the box on mount and the checkmark when checked.
   * Defaults to the DoodleUIProvider value (true).
   */
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

const BOX = 20;
const CHECK_PATH = "M 4.5 10.5 L 8.5 14.5 L 15.5 5.5";

function CheckMark({
  roughness,
  seed,
  sketchColor,
  bowing,
  strokeWidth,
  shouldAnimate,
}: {
  roughness?: number;
  seed?: number;
  sketchColor?: string;
  bowing?: number;
  strokeWidth?: number;
  shouldAnimate: boolean;
}) {
  const { roughness: baseRoughness } = useSketchDefaults();
  const ref = useRef<HTMLSpanElement>(null);
  useDrawIn(ref, DRAW_IN_MARK_MS, shouldAnimate);

  return (
    <span
      ref={ref}
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
    >
      <RoughSvg
        shape="path"
        path={CHECK_PATH}
        roughness={(roughness ?? baseRoughness) * 0.7}
        seed={seed}
        sketchColor={sketchColor}
        bowing={bowing}
        strokeWidth={(strokeWidth ?? 1.6) + 0.4}
        inset={0}
      />
    </span>
  );
}

/**
 * Square checkbox with a drawn checkmark.
 *
 * @example
 * <Checkbox />
 */
export const Checkbox = forwardRef<HTMLButtonElement, CheckboxProps>(
  function Checkbox(
    {
      className,
      style,
      label,
      fill,
      roughness,
      seed,
      sketchColor,
      bowing,
      fillStyle,
      strokeWidth,
      hachureGap,
      hachureAngle,
      fillWeight,
      checked,
      defaultChecked,
      onCheckedChange,
      id,
      animate,
      ...rest
    },
