import type { SketchProps } from "../types";
import { cn, doodleUiFontFamily, doodleUiFontWeight } from "../utils";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import { useSketchTheme } from "../hooks/useSketchTheme";

const CHEVRON_PATH = "M 6 4 L 12 10 L 6 16";

interface CollapsibleSketchContextValue extends SketchProps {
  resolvedSeed: number;
  ink: string;
  open: boolean;
}

const CollapsibleSketchContext =
  createContext<CollapsibleSketchContextValue | null>(null);

function useCollapsibleSketch(): CollapsibleSketchContextValue {
  const ctx = useContext(CollapsibleSketchContext);
  if (!ctx) {
    throw new Error(
      "Collapsible parts must be used inside <Collapsible>.",
    );
  }
  return ctx;
}

/**
 * Props for {@link Collapsible}.
 */
export interface CollapsibleProps
  extends Omit<CollapsiblePrimitive.CollapsibleProps, "asChild">,
    SketchProps {
  children?: ReactNode;
}

/**
 * Single collapsible section.
 *
 * @example
 * <Collapsible />
 */
export const Collapsible = forwardRef<HTMLDivElement, CollapsibleProps>(
  function Collapsible(
    {
      className,
      style,
      children,
      open,
      defaultOpen,
      onOpenChange,
      disabled,
      roughness,
      seed,
      sketchColor,
      bowing,
      fillStyle,
      strokeWidth,
      hachureGap,
      hachureAngle,
      fillWeight,
      ...rest
    },
    ref,
  ) {
    const resolvedSeed = useResolvedSeed(seed);
    const theme = useSketchTheme(sketchColor);
    const ink = sketchColor ?? theme.ink;
    const [uncontrolled, setUncontrolled] = useState(defaultOpen ?? false);
    const isOpen = open ?? uncontrolled;

    return (
      <CollapsibleSketchContext.Provider
        value={{
          roughness,
          seed: resolvedSeed,
          sketchColor: ink,
          bowing,
          fillStyle,
          strokeWidth,
          hachureGap,
          hachureAngle,
          fillWeight,
          resolvedSeed,
          ink,
          open: isOpen,
        }}
      >
        <CollapsiblePrimitive.Root
          ref={ref}
          open={isOpen}
          disabled={disabled}
          className={cn(className)}
          style={style}
          onOpenChange={(next) => {
            setUncontrolled(next);
            onOpenChange?.(next);
          }}
          {...rest}
        >
          {children}
        </CollapsiblePrimitive.Root>
      </CollapsibleSketchContext.Provider>
    );
  },
);

