              fontSize: 14,
              fontWeight: doodleUiFontWeight(500),
              color: ink,
              cursor: disabled ? "not-allowed" : "pointer",
              appearance: "none",
              WebkitAppearance: "none",
              MozAppearance: "none",
              outline: "none",
            }}
            {...rest}
          >
            {options
              ? options.map((opt) => (
                  <option
                    key={opt.value}
                    value={opt.value}
                    disabled={opt.disabled}
                  >
                    {opt.label}
                  </option>
                ))
              : children}
          </select>
          <span
            aria-hidden
            style={{
              position: "absolute",
              right: 10,
              top: "50%",
              transform: "translateY(-50%)",
              width: 20,
              height: 14,
              pointerEvents: "none",
              zIndex: 2,
            }}
          >
            <RoughSvg
              shape="path"
              path={CHEVRON_PATH}
              roughness={(roughness ?? baseRoughness) * 0.85}
              seed={resolvedSeed}
              sketchColor={ink}
              bowing={bowing}
              strokeWidth={strokeWidth ?? 1.5}
            />
          </span>
        </span>
      </span>
    );
  },
);

