const CHEVRON_PATH = "M 4 6 L 10 12 L 16 6";
const UNDERLINE_INSET = 4;

export interface SelectOption {
  value: string;
  label: ReactNode;
  disabled?: boolean;
}

interface SelectSketchContextValue extends SketchProps {
  resolvedSeed: number;
  ink: string;
  paper: string;
  accent: string;
  selectedValue?: string;
  selectedLabel?: ReactNode;
  placeholder?: string;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

const SelectSketchContext = createContext<SelectSketchContextValue | null>(
  null,
);

function useSelectSketch(): SelectSketchContextValue {
  const ctx = useContext(SelectSketchContext);
  if (!ctx) {
    throw new Error("Select parts must be used inside <Select>.");
  }
  return ctx;
}

/**
 * Props for {@link Select}.
 */
export interface SelectProps
  extends Omit<SelectPrimitive.SelectProps, "children">,
    SketchProps {
  options: SelectOption[];
  placeholder?: string;
  className?: string;
  style?: CSSProperties;
  fill?: string;
  "aria-label"?: string;
  /**
   * Draw-in the trigger on mount and the popover border on open.
   * Defaults to the DoodleUIProvider value (true).
   */
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

/**
 * Dropdown select with sketch trigger and menu.
 *
 * @example
 * <Select />
 */
export function Select({
  options,
  placeholder = "Select…",
  className,
  style,
  fill,
  roughness,
  seed,
  sketchColor,
  bowing,
  fillStyle,
  strokeWidth,
  hachureGap,
  hachureAngle,
  fillWeight,
  value,
  defaultValue,
  onValueChange,
  animate,
  "aria-label": ariaLabel,
  ...rest
}: SelectProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const selectedValue = value ?? uncontrolled;
  const selectedLabel = options.find((option) => option.value === selectedValue)
    ?.label;
  const resolvedSeed = useResolvedSeed(seed);
  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;

  return (
    <SelectSketchContext.Provider
      value={{
        roughness,
        seed: resolvedSeed,
        sketchColor,
        bowing,
        fillStyle,
        strokeWidth,
        hachureGap,
        hachureAngle,
        fillWeight,
        resolvedSeed,
        ink,
        paper: fill ?? theme.paper,
        accent: theme.accent,
        selectedValue,
        selectedLabel,
        placeholder,
        animate,
      }}
    >
      <SelectPrimitive.Root
        value={value}
        defaultValue={defaultValue}
        onValueChange={(next) => {
          setUncontrolled(next);
          onValueChange?.(next);
        }}
        {...rest}
      >
        <SelectTrigger
          className={className}
          style={style}
          placeholder={placeholder}
          aria-label={ariaLabel}
        />
        <SelectContent>
          {options.map((option) => (
            <SelectItem
              key={option.value}
              value={option.value}
              disabled={option.disabled}
            >
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </SelectPrimitive.Root>
    </SelectSketchContext.Provider>
  );
}

/**
 * Props for {@link SelectTrigger}.
 */
export interface SelectTriggerProps
  extends Omit<SelectPrimitive.SelectTriggerProps, "asChild"> {
  placeholder?: string;
}

export const SelectTrigger = forwardRef<HTMLButtonElement, SelectTriggerProps>(
  function SelectTrigger(
    { className, style, placeholder, children, ...rest },
    ref,
  ) {
    const sketch = useSelectSketch();
    const [openish, setOpenish] = useState(false);
    const rootRef = useRef<HTMLButtonElement>(null);
    const { roughness: baseRoughness } = useSketchDefaults();
    const shouldAnimate = useAnimate(sketch.animate);
    useDrawIn(rootRef, DRAW_IN_DURATION_MS, shouldAnimate);

    return (
      <SelectPrimitive.Trigger
        ref={(node) => {
          (rootRef as MutableRefObject<HTMLButtonElement | null>).current =
            node;
          assignRef(ref, node);
        }}
        className={cn(className)}
        onPointerDown={() => setOpenish(true)}
        onBlur={() => setOpenish(false)}
        style={{
          position: "relative",
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 12,
          minWidth: 180,
          minHeight: 38,
          padding: "8px 12px",
          border: "none",
          background: "transparent",
          cursor: "pointer",
          color: sketch.ink,
          fontFamily: doodleUiFontFamily,
          fontSize: 15,
          lineHeight: 1.2,
          outline: "none",
          textAlign: "left",
          ...style,
        }}
        {...rest}
      >
        <RoughSvg
          shape="rectangle"
          roughness={sketch.roughness}
          seed={sketch.resolvedSeed}
          sketchColor={openish ? sketch.accent : sketch.ink}
          bowing={sketch.bowing}
          fillStyle={sketch.fillStyle}
          strokeWidth={
            openish
              ? (sketch.strokeWidth ?? 1.75) + 0.35
              : sketch.strokeWidth
          }
        />
        <span
          style={{
            position: "relative",
            zIndex: 1,
            flex: 1,
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap",
          }}
        >
          {children ?? sketch.selectedLabel ?? placeholder}
