const SIDEBAR_WIDTH = 240;
const SIDEBAR_WIDTH_COLLAPSED = 56;

interface SidebarContextValue {
  open: boolean;
  setOpen: (open: boolean) => void;
  collapsed: boolean;
  toggleCollapsed: () => void;
  ink: string;
  paper: string;
  sketch: SketchProps;
}

const SidebarContext = createContext<SidebarContextValue | null>(null);

/**
 * Sidebar layout state from {@link SidebarProvider}.
 *
 * @returns Open/collapse flags, palette tokens, and shared sketch props.
 * @throws When used outside `<SidebarProvider>`.
 *
 * @example
 * const { collapsed, toggleCollapsed } = useSidebar();
 */
export function useSidebar(): SidebarContextValue {
  const ctx = useContext(SidebarContext);
  if (!ctx) {
    throw new Error("Sidebar parts must be used inside <SidebarProvider>.");
  }
  return ctx;
}

/**
 * Props for {@link SidebarProvider}.
 */
export interface SidebarProviderProps extends SketchProps {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  defaultCollapsed?: boolean;
  children?: ReactNode;
}

export function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange,
  defaultCollapsed = false,
  children,
  roughness,
  seed,
  sketchColor,
  bowing,
  strokeWidth,
}: SidebarProviderProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const [collapsed, setCollapsed] = useState(defaultCollapsed);
  const open = openProp ?? uncontrolledOpen;
  const setOpen = useCallback(
    (next: boolean) => {
      onOpenChange?.(next);
      if (openProp === undefined) {
        setUncontrolledOpen(next);
      }
    },
    [onOpenChange, openProp],
  );
  const toggleCollapsed = useCallback(() => {
    setCollapsed((c) => !c);
  }, []);
  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;
  const paper = theme.paper;
  const value = useMemo(
    () => ({
      open,
      setOpen,
      collapsed,
      toggleCollapsed,
      ink,
      paper,
      sketch: { roughness, seed, sketchColor: ink, bowing, strokeWidth },
    }),
    [
      open,
      setOpen,
      collapsed,
      toggleCollapsed,
      ink,
      paper,
      roughness,
      seed,
      bowing,
      strokeWidth,
    ],
  );

  return (
    <SidebarContext.Provider value={value}>{children}</SidebarContext.Provider>
  );
}

/**
 * Props for {@link Sidebar}.
 */
export interface SidebarProps extends HTMLAttributes<HTMLElement> {
  side?: "left" | "right";
  fill?: string;
}

/**
 * Collapsible application sidebar layout.
 *
 * @example
 * <Sidebar />
 */
export const Sidebar = forwardRef<HTMLElement, SidebarProps>(function Sidebar(
  { className, style, children, fill, side = "left", ...rest },
  ref,
) {
  const { open, collapsed, ink, paper, sketch } = useSidebar();
  const resolvedSeed = useResolvedSeed(sketch.seed);
  const width = collapsed ? SIDEBAR_WIDTH_COLLAPSED : SIDEBAR_WIDTH;

  if (!open) {
    return null;
  }

  return (
    <aside
      ref={ref}
      className={cn(className)}
      style={{
        position: "relative",
        flexShrink: 0,
        width,
        minHeight: 200,
        transition: "width 200ms ease",
        display: "flex",
        flexDirection: "column",
        background: fill ?? paper,
        color: ink,
        ...style,
      }}
      data-side={side}
      {...rest}
    >
      {children}
      <span
        aria-hidden
        style={{
          position: "absolute",
          top: 0,
          bottom: 0,
          width: 4,
          ...(side === "left" ? { right: 0 } : { left: 0 }),
          pointerEvents: "none",
        }}
      >
        <RoughSvg
          shape="line-vertical"
          roughness={sketch.roughness}
          seed={resolvedSeed}
          sketchColor={sketch.sketchColor ?? ink}
          bowing={sketch.bowing}
          strokeWidth={sketch.strokeWidth ?? 1.5}
        />
      </span>
    </aside>
  );
});

