      ComponentPropsWithoutRef<typeof SliderPrimitive.Root>,
      "asChild"
    >,
    SketchProps {
  thumbShape?: SliderThumbShape;
  fill?: string;
}

/**
 * Range slider with sketch track and thumb.
 *
 * @example
 * <Slider />
 */
export const Slider = forwardRef<HTMLSpanElement, SliderProps>(function Slider(
  {
    className,
    style,
    fill,
    roughness,
    seed,
    sketchColor,
    bowing,
    fillStyle,
    strokeWidth,
    hachureGap,
    hachureAngle,
    fillWeight,
    thumbShape = "circle",
    ...rest
  },
  ref,
) {
  const { roughness: baseRoughness } = useSketchDefaults();
  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;
  const accent = sketchColor ?? theme.accent;
  const trackInk = sketchColor ?? (theme.isDark ? "rgba(243, 244, 246, 0.4)" : theme.ink);
  const resolvedSeed = useResolvedSeed(seed);

  return (
    <SliderPrimitive.Root
      ref={ref}
      className={cn(className)}
      style={{
        position: "relative",
        display: "flex",
        alignItems: "center",
        width: "100%",
        height: 28,
        userSelect: "none",
        touchAction: "none",
        color: ink,
        ...style,
      }}
      {...rest}
    >
      <SliderPrimitive.Track
        style={{
          position: "relative",
          flex: 1,
          height: 16,
        }}
      >
        <RoughSvg
          shape="line"
          roughness={roughness ?? baseRoughness}
          seed={resolvedSeed}
          sketchColor={trackInk}
          bowing={bowing ?? 2}
          strokeWidth={strokeWidth ?? 1.6}
          inset={4}
        />
        <SliderPrimitive.Range
          style={{
            position: "absolute",
            left: 0,
            height: "100%",
          }}
        >
          <RoughSvg
            shape="line"
            roughness={(roughness ?? baseRoughness) + 0.4}
            seed={deriveSeed(resolvedSeed, "range")}
            sketchColor={accent}
            bowing={bowing ?? 1.6}
            strokeWidth={(strokeWidth ?? 1.6) + 0.6}
            inset={4}
          />
        </SliderPrimitive.Range>
      </SliderPrimitive.Track>
      <SliderPrimitive.Thumb
        style={{
          display: "block",
          width: 20,
          height: 20,
          position: "relative",
          outline: "none",
          cursor: "grab",
        }}
      >
        <RoughSvg
          shape={thumbShape === "square" ? "rectangle" : "ellipse"}
          roughness={(roughness ?? baseRoughness) * 0.85}
          seed={deriveSeed(resolvedSeed, "thumb")}
          sketchColor={accent}
          fill={fill ?? theme.paper}
          fillStyle={fillStyle ?? "solid"}
          bowing={bowing}
          strokeWidth={(strokeWidth ?? 1.5) + 0.3}
          hachureGap={hachureGap}
          hachureAngle={hachureAngle}
          fillWeight={fillWeight}
          inset={1}
        />
      </SliderPrimitive.Thumb>
    </SliderPrimitive.Root>
  );
});

"use client";

import { useSketchDefaults } from "../hooks/useSketchDefaults";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { motion } from "framer-motion";
import { useAnimate } from "../animations";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { RoughSvg } from "../primitives/RoughSvg";
import type { SketchProps } from "../types";
import { cn } from "../utils";

/** Partial circle arc for a 24×24 viewBox */
const SPINNER_ARC = "M 12 3 A 9 9 0 1 1 11.5 3";

export type SpinnerSize = "sm" | "md" | "lg";

const SIZE_PX: Record<SpinnerSize, number> = {
  sm: 18,
  md: 24,
  lg: 32,
};

/**
 * Props for {@link Spinner}.
 */
export interface SpinnerProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "color">,
    SketchProps {
  /**
   * Control size preset.
   * @default "md"
   */
  size?: SpinnerSize;
  /**
   * Continuous rotation. Defaults to the DoodleUIProvider value (true).
   * Reduced motion shows a static arc.
   */
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

/**
 * Animated hand-drawn loading arc.
 *
 * @example
 * <Spinner />
 */
export const Spinner = forwardRef<HTMLDivElement, SpinnerProps>(
  function Spinner(
    {
      className,
      style,
      size = "md",
      roughness,
      seed,
      sketchColor,
      bowing,
      fillStyle,
      strokeWidth,
      animate,
      ...rest
    },
    ref,
  ) {
    const px = SIZE_PX[size];
    const resolvedSeed = useResolvedSeed(seed);
    const { roughness: baseRoughness } = useSketchDefaults();
    const theme = useSketchTheme(sketchColor);
    const ink = sketchColor ?? theme.ink;
    const shouldSpin = useAnimate(animate);

    const boxStyle: CSSProperties = {
      position: "relative",
      width: px,
      height: px,
      flexShrink: 0,
      display: "inline-block",
      ...style,
    };

    const arc = (
      <RoughSvg
        shape="path"
        path={SPINNER_ARC}
        width={px}
        height={px}
        roughness={roughness ?? baseRoughness}
        seed={resolvedSeed}
        sketchColor={ink}
        bowing={bowing ?? 1.2}
        fillStyle={fillStyle}
        strokeWidth={strokeWidth ?? 2}
        inset={2}
      />
    );

    return (
      <div
        ref={ref}
        role="status"
        aria-label="Loading"
        className={cn(className)}
        style={boxStyle}
        {...rest}
      >
        {shouldSpin ? (
          <motion.div
            style={{ position: "absolute", inset: 0 }}
            animate={{ rotate: 360 }}
            transition={{
              duration: 0.9,
              ease: "linear",
              repeat: Infinity,
            }}
          >
            {arc}
          </motion.div>
        ) : (
          arc
        )}
      </div>
    );
  },
);

