import {
  DRAW_IN_DURATION_MS,
  useAnimate,
  useDrawIn,
} from "../animations";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { RoughSvg } from "../primitives/RoughSvg";
import type { SketchProps } from "../types";
import { assignRef, cn, deriveSeed, doodleUiFontFamily, doodleUiFontWeight } from "../utils";

export type ToggleSize = "sm" | "md" | "lg";

const SIZE_STYLES: Record<ToggleSize, { fontSize: number; padding: string; minHeight: number }> =
  {
    sm: { fontSize: 13, padding: "4px 10px", minHeight: 30 },
    md: { fontSize: 15, padding: "7px 14px", minHeight: 38 },
    lg: { fontSize: 17, padding: "10px 18px", minHeight: 46 },
  };

/**
 * Props for {@link Toggle}.
 */
export interface ToggleProps
  extends Omit<TogglePrimitive.ToggleProps, "asChild">,
    SketchProps {
  /**
   * Control size preset.
   * @default "md"
   */
  size?: ToggleSize;
  /**
   * Draw-in on mount and seed morph on press.
   * Defaults to the DoodleUIProvider value (true).
   */
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

/**
 * Pressed/unpressed sketch toggle button.
 *
 * @example
 * <Toggle />
 */
export const Toggle = forwardRef<HTMLButtonElement, ToggleProps>(
  function Toggle(
    {
      className,
      style,
      size = "md",
      roughness,
      seed,
      sketchColor,
      bowing,
      fillStyle,
      strokeWidth,
      hachureGap,
      hachureAngle,
      fillWeight,
      pressed,
      defaultPressed,
      onPressedChange,
      disabled,
      animate,
      children,
      ...rest
    },
    ref,
  ) {
    const rootRef = useRef<HTMLButtonElement>(null);
    const [uncontrolled, setUncontrolled] = useState(defaultPressed === true);
    const isPressed = pressed ?? uncontrolled;
    const theme = useSketchTheme(sketchColor);
    const ink = sketchColor ?? theme.ink;
    const accent = sketchColor ?? theme.accent;
    const accentFill = theme.isDark
      ? (sketchColor ? `${sketchColor}25` : theme.accentFill)
      : theme.accentFill;
    const resolvedSeed = useResolvedSeed(seed);
    const shouldAnimate = useAnimate(animate);
    const pressSeed = deriveSeed(resolvedSeed, isPressed ? "on" : "off");
    const sketchSeed = shouldAnimate ? pressSeed : resolvedSeed;

    useDrawIn(rootRef, DRAW_IN_DURATION_MS, shouldAnimate, sketchSeed);

    return (
      <TogglePrimitive.Root
        ref={(node) => {
          (rootRef as MutableRefObject<HTMLButtonElement | null>).current = node;
          assignRef(ref, node);
        }}
        pressed={pressed}
        defaultPressed={defaultPressed}
        onPressedChange={(next) => {
          setUncontrolled(next);
          onPressedChange?.(next);
        }}
        disabled={disabled}
        className={cn(className)}
        style={{
          position: "relative",
          display: "inline-flex",
          alignItems: "center",
          justifyContent: "center",
          border: "none",
          background: "transparent",
          cursor: disabled ? "not-allowed" : "pointer",
          color: isPressed ? (theme.isDark ? "#ffffff" : accent) : ink,
          fontFamily: doodleUiFontFamily,
          fontWeight: doodleUiFontWeight(600),
          opacity: disabled ? 0.45 : 1,
          outline: "none",
          ...SIZE_STYLES[size],
          ...style,
        }}
        {...rest}
      >
        <RoughSvg
          shape="rectangle"
          roughness={roughness}
          seed={sketchSeed}
          sketchColor={isPressed ? accent : ink}
          bowing={bowing}
          fillStyle={fillStyle ?? "hachure"}
          fill={isPressed ? accentFill : undefined}
          strokeWidth={strokeWidth ?? 1.6}
          hachureGap={hachureGap ?? 7}
          hachureAngle={hachureAngle}
          fillWeight={fillWeight ?? 1}
        />
        <span style={{ position: "relative", zIndex: 1 }}>{children}</span>
      </TogglePrimitive.Root>
    );
  },
);

"use client";

import {
  createContext,
  forwardRef,
  useContext,
  useLayoutEffect,
  useRef,
  useState,
  type MutableRefObject,
  type ReactNode,
} from "react";
import * as ToggleGroupPrimitive from "@radix-ui/react-toggle-group";
import {
  DRAW_IN_DURATION_MS,
  useAnimate,
  useDrawIn,
} from "../animations";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { RoughSvg } from "../primitives/RoughSvg";
import type { SketchProps } from "../types";
import { cn, assignRef, deriveSeed, doodleUiFontFamily, doodleUiFontWeight } from "../utils";
import type { ToggleSize } from "./Toggle";

interface ToggleGroupSketchContextValue extends SketchProps {
  resolvedSeed: number;
  ink: string;
  accent: string;
  accentFill: string;
  isDark: boolean;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
  size: ToggleSize;
}

const ToggleGroupSketchContext =
  createContext<ToggleGroupSketchContextValue | null>(null);

function useToggleGroupSketch(): ToggleGroupSketchContextValue {
  const ctx = useContext(ToggleGroupSketchContext);
  if (!ctx) {
    throw new Error("ToggleGroupItem must be used inside <ToggleGroup>.");
  }
  return ctx;
}

export type ToggleGroupProps = SketchProps & {
  children?: ReactNode;
  /**
   * Control size preset.
   * @default "md"
   */
  size?: ToggleSize;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
} & (
  | ({ type?: "single" } & Omit<
      ToggleGroupPrimitive.ToggleGroupSingleProps,
      "type" | "children"
    >)
  | ({ type: "multiple" } & Omit<
      ToggleGroupPrimitive.ToggleGroupMultipleProps,
      "type" | "children"
    >)
);

/**
 * Group of sketch toggle buttons.
 *
 * @example
 * <ToggleGroup />
 */
export function ToggleGroup(props: ToggleGroupProps) {
  const {
    children,
    roughness,
    seed,
    sketchColor,
    bowing,
    fillStyle,
    strokeWidth,
    hachureGap,
    hachureAngle,
    fillWeight,
    size = "md",
    animate,
    type = "single",
    ...rest
  } = props;
  const resolvedSeed = useResolvedSeed(seed);
  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;
  const accent = sketchColor ?? theme.accent;
  const accentFill = theme.isDark
    ? (sketchColor ? `${sketchColor}25` : theme.accentFill)
    : theme.accentFill;

  const rootStyle = { display: "inline-flex", gap: 6, flexWrap: "wrap" as const };

  return (
    <ToggleGroupSketchContext.Provider
      value={{
        roughness,
        seed: resolvedSeed,
        sketchColor,
        bowing,
        fillStyle,
        strokeWidth,
        hachureGap,
        hachureAngle,
        fillWeight,
        resolvedSeed,
        ink,
        accent,
        accentFill,
        isDark: theme.isDark,
        animate,
        size,
      }}
    >
      {type === "multiple" ? (
        <ToggleGroupPrimitive.Root
          type="multiple"
          style={rootStyle}
          {...(rest as Omit<
            ToggleGroupPrimitive.ToggleGroupMultipleProps,
            "type" | "children"
          >)}
        >
          {children}
        </ToggleGroupPrimitive.Root>
      ) : (
        <ToggleGroupPrimitive.Root
          type="single"
          style={rootStyle}
          {...(rest as Omit<
            ToggleGroupPrimitive.ToggleGroupSingleProps,
            "type" | "children"
          >)}
        >
          {children}
        </ToggleGroupPrimitive.Root>
      )}
    </ToggleGroupSketchContext.Provider>
  );
}

const ITEM_SIZE: Record<
  ToggleSize,
  { fontSize: number; padding: string; minHeight: number }
> = {
  sm: { fontSize: 13, padding: "4px 10px", minHeight: 30 },
  md: { fontSize: 15, padding: "7px 14px", minHeight: 38 },
  lg: { fontSize: 17, padding: "10px 18px", minHeight: 46 },
};

/**
 * Props for {@link ToggleGroupItem}.
 */
export interface ToggleGroupItemProps
  extends Omit<ToggleGroupPrimitive.ToggleGroupItemProps, "asChild"> {
  children?: ReactNode;
}

export const ToggleGroupItem = forwardRef<
  HTMLButtonElement,
  ToggleGroupItemProps
>(function ToggleGroupItem(
  { className, style, children, value, disabled, ...rest },
  ref,
) {
  const sketch = useToggleGroupSketch();
  const rootRef = useRef<HTMLButtonElement>(null);
  const [pressed, setPressed] = useState(false);
  const shouldAnimate = useAnimate(sketch.animate);
  const pressSeed = deriveSeed(
    sketch.resolvedSeed,
    `${value}-${pressed ? "on" : "off"}`,
  );
  const sketchSeed = shouldAnimate ? pressSeed : sketch.resolvedSeed;

  useLayoutEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const sync = () => setPressed(el.getAttribute("data-state") === "on");
    sync();
    const obs = new MutationObserver(sync);
    obs.observe(el, { attributes: true, attributeFilter: ["data-state"] });
    return () => obs.disconnect();
  }, [value]);

  useDrawIn(rootRef, DRAW_IN_DURATION_MS, shouldAnimate, sketchSeed);

  const textColor = pressed
    ? (sketch.isDark ? "#ffffff" : sketch.accent)
    : sketch.ink;

  return (
    <ToggleGroupPrimitive.Item
      ref={(node) => {
        (rootRef as MutableRefObject<HTMLButtonElement | null>).current = node;
        assignRef(ref, node);
      }}
      value={value}
      disabled={disabled}
      className={cn(className)}
      style={{
        position: "relative",
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        border: "none",
        background: "transparent",
        cursor: disabled ? "not-allowed" : "pointer",
        color: textColor,
        fontFamily: doodleUiFontFamily,
        fontWeight: doodleUiFontWeight(600),
        opacity: disabled ? 0.45 : 1,
        outline: "none",
        ...ITEM_SIZE[sketch.size],
        ...style,
      }}
      {...rest}
    >
      <RoughSvg
        shape="rectangle"
        roughness={sketch.roughness}
        seed={sketchSeed}
        sketchColor={pressed ? sketch.accent : sketch.ink}
        bowing={sketch.bowing}
        fillStyle={sketch.fillStyle ?? "hachure"}
        fill={pressed ? sketch.accentFill : undefined}
        strokeWidth={sketch.strokeWidth ?? 1.6}
        hachureGap={sketch.hachureGap ?? 7}
        hachureAngle={sketch.hachureAngle}
        fillWeight={sketch.fillWeight ?? 1}
      />
      <span style={{ position: "relative", zIndex: 1 }}>{children}</span>
    </ToggleGroupPrimitive.Item>
  );
});

"use client";

import type { ComponentPropsWithoutRef, ReactNode } from "react";
import * as TooltipPrimitive from "@radix-ui/react-tooltip";
import { DRAW_IN_TOOLTIP_MS } from "../animations";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { SketchBox } from "../primitives/SketchBox";
import type { SketchProps } from "../types";
import { cn, doodleUiFontFamily } from "../utils";

export const TooltipProvider = TooltipPrimitive.Provider;

/**
 * Props for {@link Tooltip}.
 */
export interface TooltipProps extends SketchProps {
  content: ReactNode;
  children: ReactNode;
  side?: ComponentPropsWithoutRef<typeof TooltipPrimitive.Content>["side"];
  delayDuration?: number;
  className?: string;
  fill?: string;
  /**
   * Quick draw-in when the bubble shows (~180ms). Defaults to the
   * DoodleUIProvider value (true).
   */
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

/**
 * Hover tooltip in a sketch bubble.
 *
 * @example
 * <Tooltip />
 */
export function Tooltip({
  content,
  children,
  side = "top",
  delayDuration = 200,
  className,
  fill,
  roughness,
  seed,
  sketchColor,
  bowing,
  fillStyle,
  strokeWidth,
  hachureGap,
  hachureAngle,
  fillWeight,
  animate,
}: TooltipProps) {
  const theme = useSketchTheme(sketchColor);
  const ink = sketchColor ?? theme.ink;

  return (
    <TooltipPrimitive.Root delayDuration={delayDuration}>
      <TooltipPrimitive.Trigger asChild>{children}</TooltipPrimitive.Trigger>
      <TooltipPrimitive.Portal>
        <TooltipPrimitive.Content
          side={side}
          sideOffset={8}
          className={cn(className)}
          style={{ zIndex: 60, outline: "none" }}
        >
          <SketchBox
            roughness={roughness ?? 1.3}
            seed={seed}
            sketchColor={ink}
            bowing={bowing}
            fillStyle={fillStyle ?? "solid"}
            fill={fill ?? theme.paper}
            strokeWidth={strokeWidth ?? 1.4}
            hachureGap={hachureGap}
            hachureAngle={hachureAngle}
            fillWeight={fillWeight}
            animate={animate}
            drawInDuration={DRAW_IN_TOOLTIP_MS}
            contentStyle={{
              padding: "6px 10px",
              fontSize: 13,
              lineHeight: 1.35,
              fontFamily: doodleUiFontFamily,
              color: ink,
              maxWidth: 240,
            }}
          >
            {content}
          </SketchBox>
        </TooltipPrimitive.Content>
      </TooltipPrimitive.Portal>
    </TooltipPrimitive.Root>
  );
}

"use client";

import {
  forwardRef,
  useRef,
  type HTMLAttributes,
} from "react";
import { DRAW_IN_MARK_MS, useAnimate, useDrawIn } from "../animations";
import { useResolvedSeed } from "../hooks/useResolvedSeed";
import { useSketchTheme } from "../hooks/useSketchTheme";
import { RoughSvg } from "../primitives/RoughSvg";
import { SketchBox } from "../primitives/SketchBox";
import type { SketchProps } from "../types";
import { cn, doodleUiFontFamily, doodleUiFontWeight } from "../utils";

type HeadingLevel = 1 | 2 | 3 | 4 | 5 | 6;
type HeadingAccent = "none" | "underline" | "highlight";

const HEADING_SIZES: Record<HeadingLevel, number> = {
  1: 32,
  2: 26,
  3: 22,
  4: 18,
  5: 16,
  6: 14,
};

/**
 * Props for {@link Heading}.
 */
export interface HeadingProps
  extends Omit<HTMLAttributes<HTMLHeadingElement>, "color">,
    SketchProps {
  level?: HeadingLevel;
  accent?: HeadingAccent;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

export const Heading = forwardRef<HTMLHeadingElement, HeadingProps>(
  function Heading(
    {
      level = 2,
      accent = "none",
      className,
      style,
      children,
      roughness,
      seed,
      sketchColor,
      bowing,
      strokeWidth,
      animate,
      ...rest
    },
    ref,
  ) {
    const Tag = `h${level}` as const;
    const theme = useSketchTheme(sketchColor);
    const ink = sketchColor ?? theme.ink;
    const accentColor = sketchColor ?? theme.accent;
    const accentFill = theme.isDark
      ? (sketchColor ? `${sketchColor}25` : theme.accentFill)
      : theme.accentFill;
    const resolvedSeed = useResolvedSeed(seed);
    const shouldAnimate = useAnimate(animate);
    const accentRef = useRef<HTMLSpanElement>(null);
    useDrawIn(accentRef, DRAW_IN_MARK_MS, shouldAnimate && accent !== "none");

    const fontSize = HEADING_SIZES[level];

    return (
      <Tag
        ref={ref}
        className={cn(className)}
        style={{
          position: "relative",
          margin: 0,
          fontFamily: doodleUiFontFamily,
          fontSize,
          fontWeight: doodleUiFontWeight(700),
          color: ink,
          lineHeight: 1.2,
          ...style,
        }}
        {...rest}
      >
        {accent === "highlight" ? (
          <span style={{ position: "relative", display: "inline" }}>
            <span
              ref={accentRef}
              aria-hidden
              style={{
                position: "absolute",
                left: -4,
                right: -4,
                bottom: 2,
                height: "0.45em",
                zIndex: 0,
              }}
            >
              <RoughSvg
                shape="rectangle"
                roughness={roughness}
                seed={resolvedSeed}
                sketchColor={accentColor}
                fill={accentFill}
                fillStyle="solid"
                bowing={bowing}
                strokeWidth={strokeWidth ?? 1.2}
              />
            </span>
            <span style={{ position: "relative", zIndex: 1 }}>{children}</span>
          </span>
        ) : (
          children
        )}
        {accent === "underline" ? (
          <span
            ref={accentRef}
            aria-hidden
            style={{
              display: "block",
              position: "relative",
              height: 6,
              marginTop: 4,
              maxWidth: "100%",
            }}
          >
            <RoughSvg
              shape="path"
              path="M 2 4 Q 40 1 80 5 T 160 3"
              roughness={roughness}
              seed={resolvedSeed}
              sketchColor={accentColor}
              bowing={bowing}
              strokeWidth={strokeWidth ?? 1.5}
            />
          </span>
        ) : null}
      </Tag>
    );
  },
);

/**
 * Props for {@link Text}.
 */
export interface TextProps extends HTMLAttributes<HTMLParagraphElement> {
  variant?: "body" | "lead" | "muted";
}

export const Text = forwardRef<HTMLParagraphElement, TextProps>(function Text(
  { variant = "body", className, style, children, ...rest },
  ref,
) {
  const theme = useSketchTheme();
  const sizes = { body: 14, lead: 17, muted: 13 };
  const opacity = variant === "muted" ? 0.75 : 1;
  return (
    <p
      ref={ref}
      className={cn(className)}
      style={{
        margin: 0,
        fontFamily: doodleUiFontFamily,
        fontSize: sizes[variant],
        fontWeight: doodleUiFontWeight(variant === "lead" ? 500 : 400),
        lineHeight: 1.55,
        color: theme.ink,
        opacity,
        ...style,
      }}
      {...rest}
    >
      {children}
    </p>
  );
});

export const Paragraph = Text;

/**
 * Props for {@link Blockquote}.
 */
export interface BlockquoteProps
  extends Omit<HTMLAttributes<HTMLQuoteElement>, "color">,
    SketchProps {
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

export const Blockquote = forwardRef<HTMLQuoteElement, BlockquoteProps>(
  function Blockquote(
    {
      className,
      style,
      children,
      roughness,
      seed,
      sketchColor,
      bowing,
      strokeWidth,
      animate,
      ...rest
    },
    ref,
  ) {
    const theme = useSketchTheme(sketchColor);
    const ink = sketchColor ?? theme.ink;
    const accent = sketchColor ?? theme.accent;
    const resolvedSeed = useResolvedSeed(seed);
    const shouldAnimate = useAnimate(animate);
    const ruleRef = useRef<HTMLSpanElement>(null);
    useDrawIn(ruleRef, DRAW_IN_MARK_MS, shouldAnimate);

    return (
      <blockquote
        ref={ref}
        className={cn(className)}
        style={{
          display: "flex",
          gap: 12,
          margin: 0,
          padding: "8px 0 8px 4px",
          fontFamily: doodleUiFontFamily,
          fontSize: 15,
          fontStyle: "italic",
          lineHeight: 1.5,
          color: ink,
          ...style,
        }}
        {...rest}
      >
        <span
          ref={ruleRef}
          aria-hidden
          style={{ position: "relative", width: 6, flexShrink: 0, minHeight: 40 }}
        >
          <RoughSvg
            shape="line-vertical"
            roughness={roughness}
            seed={resolvedSeed}
            sketchColor={accent}
            bowing={bowing}
            strokeWidth={strokeWidth ?? 2}
          />
        </span>
        <span>{children}</span>
      </blockquote>
    );
  },
);

