/**
 * Props for {@link Highlight}.
 */
export interface HighlightProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, "color">,
    SketchProps {
  fill?: string;
  /**
   * Play sketch draw-in animations. Defaults to {@link DoodleUIProvider} `animate` (true).
   * @default undefined (follow provider)
   */
  animate?: boolean;
}

export const Highlight = forwardRef<HTMLSpanElement, HighlightProps>(
  function Highlight(
    {
      className,
      style,
      children,
      fill,
      roughness,
      seed,
      sketchColor,
      bowing,
      strokeWidth,
      animate,
      ...rest
    },
    ref,
  ) {
    const resolvedSeed = useResolvedSeed(seed);
    const theme = useSketchTheme(sketchColor);
    const accent = sketchColor ?? theme.accent;
    const accentFill = fill ?? (theme.isDark
      ? (sketchColor ? `${sketchColor}25` : theme.accentFill)
      : theme.accentFill);
    const shouldAnimate = useAnimate(animate);
    const markRef = useRef<HTMLSpanElement>(null);
    useDrawIn(markRef, DRAW_IN_MARK_MS, shouldAnimate);

    return (
      <span
        ref={ref}
        className={cn(className)}
        style={{ position: "relative", display: "inline", ...style }}
        {...rest}
      >
        <span
          ref={markRef}
          aria-hidden
          style={{
            position: "absolute",
            left: -2,
            right: -2,
            bottom: 0,
            top: "35%",
            zIndex: 0,
          }}
        >
          <RoughSvg
            shape="rectangle"
            roughness={roughness}
            seed={resolvedSeed}
            sketchColor={accent}
            fill={accentFill}
            fillStyle="solid"
            bowing={bowing}
            strokeWidth={strokeWidth ?? 1}
          />
        </span>
        <span style={{ position: "relative", zIndex: 1 }}>{children}</span>
      </span>
    );
  },
);
